\section{Chromatic number upper bound}\label{sec:general}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Given a temporal graph, we remind that its temporal chromatic number is lower bounded by the maximum chromatic number of each union of three consecutive snapshots. The two following results define upper bounds of temporal chromatic number, based on the chromatic number of each snapshot, and on the chromatic number of unions of three consecutive snapshots.


\begin{theorem} \label{th:cubeub}
Let $\mathcal{G}=(G_1,\ldots,G_T)$ be a temporal graph. %with vertex set $V$. 
%
If for all $i\in[T]$, $\chi(G_i) \leq k$, then $\chi^t({\cal G})\leq k^3$.
\end{theorem}
%}
\begin{proof}
Let $K = \{ (i,j,t) \mid i,j,t \in [k] \}$ be a set of $k^3$ colors. 


For $i\in\{1,\ldots,T\}$, let $x_i : V\rightarrow [k]$ be a proper $k$-coloring of $G_i$. We define a coloring $c_i : V \rightarrow K$ for $i\in [T]$ as follows:
\begin{itemize}
    \item If $i = 0$ mod 3, let $c_i(v) = (x_{i}(v),x_{i+1}(v),x_{i-1}(v))$

    \item If $i = 1$ mod 3, let $c_i(v) = (x_{i-1}(v),x_{i}(v),x_{i+1}(v))$

    \item If $i = 2$ mod 3, let $c_i(v) = (x_{i+1}(v),x_{i-1}(v),x_{i}(v))$

\end{itemize}

\vspace{0.75ex}

\noindent The sequence $(c_1,\ldots,c_T)$ is a temporal $k^3$-coloring of $\mathcal{G}$ since, for every $i \in [T]$:
\begin{enumerate}
    \item Coloring $c_i$ is a proper coloring for $S_i({\cal G})$. Let $uv \in E_{i-1} \cup E_i \cup E_{i+1}$, then either $x_{i-1}(u) \neq x_{i-1}(v)$ or $x_i(u) \neq x_i(v)$ or $x_{i+1}(u) \neq x_{i+1}(v)$. It implies that $c_i(v) \neq c_i(u)$.
    \item If $i\neq T$, $c_i$ is compatible with $c_{i+1}$ in $E_i \cup E_{i+1}$. Let $uv \in E_i \cup E_{i+1}$, then either $x_i(u) \neq x_i(v)$ or $x_{i+1}(u) \neq x_{i+1}(v)$. It implies that $c_i(v) \neq c_{i+1}(u)$.
\end{enumerate}
\end{proof}

