The following result gives an upper bound on the number of colors needed when we double each snapshot. More precisely, if each snapshot is $k$-colorable, the temporal graph needs at most $k^2$ colors, compared to the $k^3$ from Theorem~\ref{th:cubeub}. This motivates the idea to duplicate snapshots (i.e. take two steps) in order to save some colors. In particular, it allows to change colors while the set of edges is stable and keep the same coloring when the set of edges evolves. More formally, duplicating snapshots corresponds to the following constrain: for all $i\in [T]$, if $E_i\sm E_{i+1}\neq \emptyset$ then $E_{i-1}\sm E_{i}= \emptyset$. In other words, changes on the edges set cannot occur two consecutive time. 

\begin{theorem}\label{th:copy}
Let $\mathcal{G} = (G_1$, $G_2$, \ldots, $G_T)$ be a temporal graph with $T$ even in which $G_{2i-1}=G_{2i}$ for all $i\in[T/2]$ (i.e. there are two consecutive copies for each snapshot). If for all $i \in [T]$, $\chi(G_i) \leq k$, then $\chi^t(\mathcal{G})\le k^2$.
\end{theorem}

\begin{proof}
For each $i\in[T/2]$, set $H_i=G_{2i-1}=G_{2i}$. In particular, $\mathcal{G} = (H_1$, $H_1$, $H_2$, $H_2$, $\ldots$, $H_{T/2}$, $H_{T/2})$.

This proof is similar as the proof of Theorem~\ref{th:cubeub}. Let  $K = \{ (i,j) \mid i,j \in [k] \}$ be the set of $k^2$ colors.

For $i\in[T/2]$, let $x_i : V\rightarrow \{1,\dots k\}$ be a proper $k$-coloring of $H_i$. Let  $(c_1^1$, $c_1^2$, $c_2^1$, $c_2^2$, $\ldots$, $c_{T/2}^1$, $c_{T/2}^2)$ be sequence of colors such that:
\begin{enumerate}
    \item For $i \in [T/2]$, if $i$ is even, $c_i^2(v) = (x_{i}(v),x_{i+1}(v))$; if $i$ is odd, $c_i^2(v) = (x_{i+1}(v),x_{i}(v))$; 
    \item Let $c_1^1 = c_1^2$, and for $i\ge2$, $c_i^1 = c_{i-1}^2$.
\end{enumerate}

We claim that $(c_1^1$, $c_1^2$, $c_2^1$, $c_2^2$, $\ldots$, $c_{T/2}^1$, $c_{T/2}^2)$ is a $k^2$-coloring of $\mathcal{G}$. In particular, we prove that the sequence is compatible and that for $i\in [T/2]$ $c^1_i$ is a proper coloring of $S_{2i-1}({\cal G})$ and $c^2_i$ is a proper coloring of $S_{2i}({\cal G})$. 



Recall that $\mathcal{G}$ can be seen as the sequence $(H_1$, $H_1$, $H_2$, $H_2$, $\ldots$, $H_{T/2}$, $H_{T/2})$.

\begin{enumerate}
    \item  For $i\in\{2,\ldots,T/2-1\}$, given a vertex $u$, we have that $c_i^1(u)=(x_{i-1}(u),x_i(u))$ or $c_i^1(u)=(x_i(u),x_{i-1}(u))$. Therefore $c_i^1$ is a proper coloring for $H_{i-1}\cup H_{i}$. Directly from the definition, we have that $c_i^2$ is a proper coloring for $H_i \cup H_{i+1}$.  Since  $S_{2i-1}(\mathcal{G})=H_{i-1}\cup H_{i}$ and $S_{2i}(\mathcal{G})=H_{i}\cup H_{i+1}$, it follows that $c^1_i$ is a proper coloring of $S_{2i-1}({\cal G})$ and $c^2_i$ is a proper coloring of $S_{2i}({\cal G})$. Using same arguments, we also have the result for $i=1$ and $i=T/2$. 
    \item For $i\in [T/2]$, since $c_{i}^1=c_{i-1}^2$, they are directly compatible in $H_i\cup H_{i+1}=G_{2i}\cup G_{2i+1}$. Recall that $G_{2i-1}\cup G_{2i}=H_i$. Hence $c^1_i$ and $c^2_i$ are compatible as, for any edge $uv\in H_i$, $x_i(u)\neq x_i(v)$ and $x_i$ appears on the same coordinate in both $c^1_i$ and $c^2_i$. 
\end{enumerate}

Hence, $(c_1^1$, $c_1^2$, $c_2^1$, $c_2^2$, $\ldots$, $c_{T/2}^1$, $c_{T/2}^2)$ is a $k^2$-coloring of $\mathcal{G}$. Therefore $\chi^t(\mathcal{G})\le k^2$.
\end{proof}




