Given a temporal graph of form $\mathcal{G} = (G_1$, $G_1$, $G_2$, $G_2$, $\ldots$, $G_T$, $G_T)$, in which, there are two consecutive copies for each snapshot, and $\chi(G_i) \leq k$, for all $i \in [T]$. Then, there exists a $k^2$-coloring $(c_1^1$, $c_1^2$, $c_2^1$, $c_2^2$, $\ldots$, $c_T^{1}$, $c_T^2)$ for $\mathcal{G}$, satisfying Definition~\Ref{Re2}.
\end{theorem}
\begin{proof}
Let $K = \{ (i,j) \mid i,j \in [k] \}$ be the set of $k^2$ colors.

For $i\in\{1,\ldots,T\}$, let $x_i : V\rightarrow \{1,\dots k\}$ be a proper $k$-coloring of $G_i$. Let  $(c_1^1$, $c_1^2$, $c_2^1$, $c_2^2$, $\ldots$, $c_T^1$, $c_T^2)$ be a $k^2$ coloring of $\mathcal{G}$ such that:
\begin{enumerate}
    \item For $i \in \{1,\ldots,T\}$. If $i$ is even, $c_i^2(v) = (x_{i}(v),x_{i+1}(v))$; If $i$ is odd, $c_i^2(v) = (x_{i+1}(v),x_{i}(v))$;
    \item Let $c_1^1 = c_1^2$, and for $i \in \{2,\ldots,T\}$, $c_i^1 = c_{i-1}^2$.
\end{enumerate}

Then, the sequence $(c_1^1$, $c_1^2$, $c_2^1$, $c_2^2$, $\ldots$, $c_T^1$, $c_T^2)$ is a $k^2$-coloring of the temporal graph G because:
\begin{enumerate}
