\end{example}


\subsection{A pair of sequences and the second construction of codebooks}
In this subsection, we study the cross-correlation of a pair of sequences and give the second construction of complex codebooks by applying the hybrid character sum $S_1$. 


\subsubsection{The cross-correlation of a pair of sequences}
To begin with, we recall the following quadratic residue mapping as follows.
 \begin{Definition}\cite{HongS}
The quadratic residue mapping $q_{m}:\gf_{p^m}\rightarrow \gf_2$ is defined as
\begin{eqnarray*}
q_m(x)=\left\{
\begin{array}{ll}
1  &   \mbox{if $\eta_m(x)=-1$},\\
0    &   \mbox{if $\eta_m(x)=1$ or $x=0$}.
\end{array} \right.
\end{eqnarray*}
 \end{Definition}




In the following, we study the cross-correlation of a pair of sequences by using the hybrid character sum $S_1$.
Let $p$ be an odd prime, $V_n^{(p)}=\gf_{p^n}$ and $F(x)$ be a vectorial dual-bent function  satisfying Condition \uppercase\expandafter{\romannumeral1}. 
This pair of sequences consists of the $p$-ary $m$-sequence 
$$\textbf{s}_1:=(\tr_{p^n/p}(\alpha^t))_{t=0}^{p^n-2}$$ and the binary sequence
$$\textbf{s}_2:=\left(q_m(F(\alpha^t)) \right)_{t=0}^{p^n-2},$$
where $\gf_{p^n}^*=\langle\alpha\rangle$.
Their cross-correlation is defined by
\begin{eqnarray*}
C(\tau)
&=&\sum_{t=0}^{p^n-2}\zeta_{p}^{\tr_{p^n/p}(\alpha^{t+\tau})}\cdot(-1)^{q_m(F(\alpha^t))}\\
&=&\sum_{x \in \gf_{p^n}^{*}}\chi_{1}(ax)\cdot(-1)^{q_{m}(F(x))},
\end{eqnarray*}
where $\tau=0,1,\cdots, p^n-2$ and $a:=\alpha^{\tau} \in \gf_{p^n}^*$.




\begin{theorem}\label{fenb}
Let $p$ be an odd prime, $V_n^{(p)}=\gf_{p^n}$ and $F(x)$ be a vectorial dual-bent function  satisfying Condition \uppercase\expandafter{\romannumeral1}. 
If $\tau$ runs over the set $\{0,1,\cdots, p^n-2\}$, then $C(\tau)$ has the following distribution:
\begin{eqnarray*}
C(\tau)=\left\{
\begin{array}{ll}
\frac{p^m-1}{p^m}\varepsilon p^{\frac{n}{2}}-1  &   \mbox{ $-1+\frac{(p^m+1)p^n+\varepsilon p^{\frac{n}{2}}(p^m-1)}{2p^m}$ times},\\
-\frac{p^m+1}{p^m}\varepsilon p^{\frac{n}{2}}-1   &   \mbox{ $\frac{(p^n-\varepsilon p^{\frac{n}{2}})(p^m-1)}{2p^m}$ times},
\end{array} \right.
\end{eqnarray*}
where  $\varepsilon\in \{\pm 1\}$ was defined in Condition \uppercase\expandafter{\romannumeral1}.
\end{theorem}


\begin{IEEEproof}
Note that
\begin{eqnarray*}
C(\tau)
&=&\sum_{x \in \gf_{p^n}^{*}}\chi_{1}(ax)\cdot(-1)^{q_{m}(F(x))}\\
&=&\sum_{x \in \gf_{p^n}^{*}}\chi_{1}(ax)\eta_{m}(F(x))+\sum_{\substack{x \in \gf_{p^n}^*\\F(x)=0}}\chi_a(x)\\
&=&S_1+\sum_{\substack{x \in \gf_{p^n}^*\\F(x)=0}}\chi_a(x).
\end{eqnarray*}
By Theorem \ref{111} and Lemma \ref{lem14}, we have 
\begin{eqnarray*}
C(\tau)=\left\{
\begin{array}{ll}
\frac{p^m-1}{p^m}\varepsilon p^{\frac{n}{2}}-1  &   \mbox{if $F^*(a)=0$ or $\eta_m(F^*(a))=1$},\\
-\frac{p^m+1}{p^m}\varepsilon p^{\frac{n}{2}}-1   &   \mbox{if $\eta_m(F^*(a))=-1$}.
\end{array} \right.
\end{eqnarray*}
By Lemma \ref{lem17}, it is easy to obtain the frequency of each value of $C(\tau)$.
\end{IEEEproof}



\begin{remark}
Let $|C(\tau)|_{\max}$ denote the maximum cross-correlation magnitude of $\textbf{s}_1$ and $\textbf{s}_2$. 
By Theorem \ref{fenb}, if $m\rightarrow +\infty$, then $|C(\tau)|_{\max}\approx p^{\frac{n}{2}}+1$, which indicates that the pair of sequences $\textbf{s}_1$ and $\textbf{s}_2$
has low maximum cross-correlation magnitude.
\end{remark}



\subsubsection{The second construction of codebooks}
Let $p$ be an odd prime, $V_n^{(p)}=\gf_{p^n}$ and $F(x)$ be a vectorial dual-bent function  satisfying Condition \uppercase\expandafter{\romannumeral1}. In the following, we present a construction of partial Hadamard codebooks.To this end, we define a row selection sequence as follows. 

\begin{Definition}\label{def3}
Define the binary row selection sequence
\begin{eqnarray*}
\mathbf{r}_m=\{r_0,r_1,\cdots,r_{p^n-1}\}
\end{eqnarray*}
by
\begin{eqnarray*}
r_k=\left\{
\begin{array}{ll}
q_m(F(\alpha^{k-1}))  &   \mbox{for $1\leq k \leq p^n-1$},\\
1    &   \mbox{for $k=0$}.
\end{array} \right.
\end{eqnarray*}
\end{Definition}

 Let $\mathbf{H}=[h_{i,j}]_{0\leq i,j\leq p^n-1}$ be the $p$-ary Hadamard matrix in Definition \ref{def1}. Let $N=p^n$ and $K=\frac{(p^n-\varepsilon p^{\frac{n}{2}})(p^m-1)}{2p^m}+1$. Let $D=\{d_0,d_1,\cdots,d_{K-1}\}$ be the support of the binary row selection sequence $\mathbf{r}_m$ in Definition \ref{def3}, where $| D|=\frac{(p^n-\varepsilon p^{\frac{n}{2}})(p^m-1)}{2p^m}+1=K$. Let $\mathcal{C}_{H}(\mathbf{r}_m)=\{\mathbf{c}_0,\mathbf{c}_1,\ldots,\mathbf{c}_{N-1}\}$ be the $(N,K)$ partial Hadamard codebook whose code vectors are the columns of the submatrix obtianed by selecting $K$ rows corresponding to $D$ from the $p^n\times p^n$ Hadamard matrix $\mathbf{H}=[h_{i,j}]_{0\leq i,j\leq p^n-1}$.



\begin{theorem}\label{777}
Let $p$ be an odd prime, $V_n^{(p)}=\gf_{p^n}$ and $F(x)$ be a vectorial dual-bent function  satisfying Condition \uppercase\expandafter{\romannumeral1}. Then $\mathcal{C}_{H}(\textbf{r}_m)$ is an $(N,K)$ asymptotically optimal partial Hadamard codebook with \begin{eqnarray*}
I_{\max}(\mathcal{C}_{H}(\mathbf{r}_m))=\max \left\{\frac{1}{2K}\left| -\frac{p^m+1}{p^m}\varepsilon p^{\frac{n}{2}}-2 \right|, \frac{1}{2K}\left| \frac{p^m-1}{p^m}\varepsilon p^{\frac{n}{2}}-2 \right| \right\},
\end{eqnarray*} where $N=p^n$ and $K=\frac{(p^n-\varepsilon p^{\frac{n}{2}})(p^m-1)}{2p^m}+1$. Let $I_{i,j}(\mathcal{C}_{H}(\textbf{r}_m))$ be the magnitude of the inner product between the code vectors $\mathbf{c}_i$ and $\mathbf{c}_j$, where $i, j$ are different integers and $0\leq i, j\leq p^n-1$. Then $I_{i,j}(\mathcal{C}_{H}(\mathbf{r}_m))$ has the following distribution:
\begin{eqnarray*}
I_{i,j}(\mathcal{C}_{H}(r_m))=\left\{
\begin{array}{ll}
\frac{1}{2K}\left|\frac{p^m-1}{p^m}\varepsilon p^{\frac{n}{2}}-2\right|  &   \mbox{ $-p^n+\frac{(p^m+1)p^{2n}+\varepsilon p^{\frac{3n}{2}}(p^m-1)}{2p^m}$ times},\\
\frac{1}{2K}\left|-\frac{p^m+1}{p^m}\varepsilon p^{\frac{n}{2}}-2\right|   &   \mbox{ $\frac{p^n(p^n-\varepsilon p^{\frac{n}{2}})(p^m-1)}{2p^m}$ times},
\end{array} \right.
\end{eqnarray*}
where  $\varepsilon\in \{\pm 1\}$ was defined in Condition \uppercase\expandafter{\romannumeral1}.
\end{theorem}
\begin{IEEEproof}
 Let $\mathbf{r}_m=\{r_0,r_1,\cdots,r_{p^n-1}\}$ be the binary row selection sequence in Definition \ref{def3}. By Lemma \ref{bina}, there exist $p^n$ distinct pairs of $(i,j)$ satisfying 
 \begin{eqnarray*}
 I_{i,j}(\mathcal{C}_{H}(\mathbf{r}_m))
 &=&\frac{1}{2K}|\widehat{r}_l|\\
  &=&\frac{1}{2K}\left|\sum_{k=0}^{p^n-1}(-1)^{r_k}h_{k,l}\right|\\
  &=&\frac{1}{2K}\left|-1+\sum_{k=1}^{p^n-1}(-1)^{q_m(F(\alpha^{k-1}))}\zeta_{p}^{\tr_{p^n/p}(\alpha^{k+l-2})}\right|\\
 &=&\frac{1}{2K}\left|-1+\sum_{k=0}^{p^n-2}(-1)^{q_m(F(\alpha^{k}))}\zeta_{p}^{\tr_{p^n/p}(\alpha^{k+l-1})}\right|\\ 
 &=&\frac{1}{2K}\left| -1+ C(l-1)\right|.
 \end{eqnarray*}
By Theorem \ref{fenb}, it is easy to obtain the value distribution of $I_{i,j}(\mathcal{C}_{H}(\mathbf{r}_m))$, where  $i, j$ are different integers and $0\leq i, j\leq p^n-1$.
It is obvious that
  \begin{eqnarray*}
I_{\max}(\mathcal{C}_{H}(\mathbf{r}_m))
&=&\max \left\{\frac{1}{2K}\left| -\frac{p^m+1}{p^m}\varepsilon p^{\frac{n}{2}}-2 \right|, \frac{1}{2K}\left| \frac{p^m-1}{p^m}\varepsilon p^{\frac{n}{2}}-2 \right| \right\}\\
 &\leq& \frac{1}{2K}\left(\frac{p^m+1}{p^m} p^{\frac{n}{2}}+2\right).
  \end{eqnarray*}
  By the Welch bound, we have
  \begin{eqnarray*}
\frac{I_{\max}(\mathcal{C}_{H}(\mathbf{r}_m))}{I_{W}}
&\leq&\frac{1}{K}\left(\frac{p^m+1}{2p^m} p^{\frac{n}{2}}+1\right)\sqrt{\frac{K(N-1)}{N-K}}\\
&=&\left(\frac{p^m+1}{2p^m} p^{\frac{n}{2}}+1\right)\sqrt{\frac{4p^{n+2m}-4p^{2m}}{p^{2n+2m}-(p^n+\varepsilon p^{\frac{n}{2}+m}-\varepsilon p^{\frac{n}{2}}-p^m)^2}}\\
&\leq&\sqrt{\frac{1+\frac{2}{p^m}+\frac{4}{p^{2m}}}{1-\frac{(p^n+\varepsilon p^{\frac{n}{2}+m}-\varepsilon p^{\frac{n}{2}}-p^m)^2}{p^{2n+2m}}}}\\
&<&\sqrt{\frac{1+\frac{4}{p^m}}{1-\frac{16}{p^{2m}}}}=\sqrt{\frac{1}{1-\frac{4}{p^m}}}.
\end{eqnarray*}
Thus $\frac{I_{\max}(\mathcal{C}_{H}(\mathbf{r}_m))}{I_{W}}\rightarrow 1$ if $p\rightarrow+\infty$ or $m\rightarrow +\infty$.
\end{IEEEproof}


 \begin{remark}
 If we fix a very small $p$ and let $m\rightarrow +\infty$, then the parameters of the codebook $\mathcal{C}_{H}(\textbf{r}_m)$  in Theorem \ref{777} 
 asymptotically achieve the Welch bound. Hence the codebook  $\mathcal{C}_{H}(\textbf{r}_m)$ could have both very small alphabet size and small maximal cross-correlation amplitude. 
 Compared to the codebook in \cite[Theorem 34]{Heng}, our codebook in Theorem \ref{777} has more abundant and flexible parameters. 
 In fact, we can obtain the codebook in \cite[Theorem 34]{Heng} from Theorem \ref{777} if $m=1$.
 \end{remark}



\subsection{The third construction of codebooks}
Let $p$ be an odd prime, $V_n^{(p)}=\gf_{p^{n_1}}\times \gf_{p^{n_2}}\times\cdots\times \gf_{p^{n_s}}$ and $F: V_{n}^{(p)}\rightarrow \gf_{p^m}$ be a vectorial dual-bent function satisfying Condition \uppercase\expandafter{\romannumeral2}. Define a set 
\begin{eqnarray*}
D_1=\left\{x\in V_n^{(p)} \setminus \{0\}: F(x)=0\right\},
\end{eqnarray*}
where $K=| D_1|$.
We define a codebook of length  $K$ as
\begin{eqnarray*}
\mathbf{c}_b=\frac{1}{\sqrt{K}}(\chi_b(x))_{x\in D_1}.
\end{eqnarray*}
Then an $(N,K)$ codebook is given as
\begin{eqnarray*}
\mathcal{C}_{D_1}=\left\{\mathbf{c}_b=\frac{1}{\sqrt{K}}(\chi_b(x))_{x\in D_1}: b \in V_n^{(p)}\right\}.
\end{eqnarray*}
It is easy to deduce that $N=p^{n}$ and $K=p^{n-m}-1$ by Lemma \ref{lem16}.


\begin{theorem}\label{666}
Let $p$ be an odd prime and $F(x)$ be a vectorial dual-bent function satisfying Condition \uppercase\expandafter{\romannumeral2}.
Let the notations be the same as those in Condition \uppercase\expandafter{\romannumeral2}.
Then $\mathcal{C}_{D_1}$ is an $(p^{n},p^{n-m}-1)$ asymptotically optimal codebook with
\begin{eqnarray*}
I_{\max}(\mathcal{C}_{D_1})=\max \left\{\frac{1}{K}\left|\frac{1}{p^m}\upsilon p^{\frac{n}{2}}(-1)^{m-1}\epsilon^m\sqrt{p^m}-1 \right|, \frac{1}{K}\left|\frac{1}{p^m}\upsilon p^{\frac{n}{2}}(-1)^{m-1}\epsilon^m\sqrt{p^m}+1\right| \right\},
\end{eqnarray*}
where $K=p^{n-m}-1$ and $\upsilon \in \{\pm\epsilon^{m}\}$ is a constant defined in Condition \uppercase\expandafter{\romannumeral2} for $\epsilon:=\sqrt{(-1)^{\frac{p-1}{2}}}$. 
Let $\mathbf{c}_{d_1}, \mathbf{c}_{d_2}$ be two codewords in $\mathcal{C}_{D_1}$ for $d_1\neq d_2$ and $d_1,d_2\in V_n^{(p)}$. Then $|\mathbf{c}_{d_1}\mathbf{c}_{d_2}^{H}|$ has the following value distribution:
\begin{eqnarray*}
\left|\mathbf{c}_{d_1}\mathbf{c}_{d_2}^{H}\right|=\left\{
\begin{array}{lll}
\frac{1}{K} &   \mbox{ $p^{2n-m}-p^{n}$ times},\\
\frac{1}{K}\left|\frac{1}{p^m}\upsilon p^{\frac{n}{2}}(-1)^{m-1}\epsilon^m\sqrt{p^m}-1\right| &   \mbox{ $p^n\frac{(p^{n-m}+(-1)^{m-1}\epsilon^m\upsilon^{-1}\eta_m(-1) p^{\frac{n-m}{2}})(p^m-1)}{2}$ times},\\
\frac{1}{K}\left|\frac{1}{p^m}\upsilon p^{\frac{n}{2}}(-1)^{m-1}\epsilon^m\sqrt{p^m}+1\right|   &   \mbox{ $p^n\frac{(p^{n-m}-(-1)^{m-1}\epsilon^m\upsilon^{-1}\eta_m(-1) p^{\frac{n-m}{2}})(p^m-1)}{2}$ times}.\\
\end{array} \right.
\end{eqnarray*}
\end{theorem}


\begin{IEEEproof}
Let $\mathbf{c}_{d_1}, \mathbf{c}_{d_2}$ be two codewords in $\mathcal{C}_{D_1}$ for $d_1\neq d_2$ and $d_1,d_2\in V_n^{(p)}$. Then
\begin{eqnarray*}
\mathbf{c}_{d_1}\mathbf{c}_{d_2}^{H}&=&\frac{1}{K}\sum_{x \in D_1} \chi_{d_1}(x)\overline{\chi_{d_2}}(x)\\
&=&\frac{1}{K}\sum_{x \in D_1} \chi_{d_1-d_2}(x)\\
&=&\frac{1}{K}\sum_{\substack{x \in V_n^{(p)}\setminus \{0\} \\F(x)=0}}\chi_{d}(x),
\end{eqnarray*}
where $d:=d_1-d_2\neq0$.
By Lemma\ref{lem15}, we have
\begin{eqnarray*}
K(\mathbf{c}_{d_1}\mathbf{c}_{d_2}^{H})&=&\left\{
\begin{array}{lll}
-1  &   \mbox{if $F^*(d)=0$},\\
\frac{1}{p^m}\upsilon p^{\frac{n}{2}}(-1)^{m-1}\epsilon^m\sqrt{p^m}-1  &   \mbox{if $\eta_m(F^*(d))=1$},\\
-\frac{1}{p^m}\upsilon p^{\frac{n}{2}}(-1)^{m-1}\epsilon^m\sqrt{p^m}-1   &   \mbox{if $\eta_m(F^*(d))=-1$}.\\
\end{array} \right.
\end{eqnarray*}
Note that for any $d \in V_n^{(p)}\backslash \{0\}$, there exist $p^n$ pairs of $(d_1,d_2)$ such that $d_1-d_2=d$.
According to Lemma \ref{lem20}, we then have 
\begin{eqnarray*}
\mathbf{c}_{d_i}\mathbf{c}_{d_j}^{H}=\left\{
\begin{array}{lll}
-\frac{1}{K} &   \mbox{ $p^{2n-m}-p^{n}$ times},\\
\frac{1}{K}\left(\frac{1}{p^m}\upsilon p^{\frac{n}{2}}(-1)^{m-1}\epsilon^m\sqrt{p^m}-1\right) &   \mbox{ $p^n\frac{(p^{n-m}+(-1)^{m-1}\epsilon^m\upsilon^{-1}\eta_m(-1) p^{\frac{n-m}{2}})(p^m-1)}{2}$ times},\\
-\frac{1}{K}\left(\frac{1}{p^m}\upsilon p^{\frac{n}{2}}(-1)^{m-1}\epsilon^m\sqrt{p^m}+1\right)   &   \mbox{ $p^n\frac{(p^{n-m}-(-1)^{m-1}\epsilon^m\upsilon^{-1}\eta_m(-1) p^{\frac{n-m}{2}})(p^m-1)}{2}$ times}.\\
\end{array} \right.
\end{eqnarray*}
Then the maximum cross-correlation magnitude follows. It is obvious that
\begin{eqnarray*}
I_{\max}(\mathcal{C}_{D_1})\leq\frac{1}{K}\left(p^{\frac{n-m}{2}}+1\right).
\end{eqnarray*}
By Lemma \ref{welch}, it is easy to verify
\begin{eqnarray*}
\frac{I_{\max}(\mathcal{C}_{D_1})}{I_{W}}\leq\frac{1}{K}(p^{\frac{n-m}{2}}+1)\sqrt{\frac{K(N-1)}{N-K}}<\sqrt{\frac{1}{1-\frac{1}{p^m}}}.
\end{eqnarray*}
Thus $\frac{I_{\max}(\mathcal{C}_{D_1})}{I_{W}}\rightarrow 1$ if $p\rightarrow+\infty$ or $m\rightarrow +\infty$.
\end{IEEEproof}



