\begin{example}
	Let~$\Sigma=\{a,b\}$ and~$\ell=3$. Let~$\bs=b_0b_1b_2b_3b_4b_5b_6b_7$ be a bitmap for a block language~$L$ such that~$b_0=b_3=b_4=1$, and the remaining bits are~$0$. We have 
	\begin{align*}
		\mathsf{R}_0 & = b_0b_1b_2b_3b_4b_5b_6b_7 \quad \text{ and } \quad \lang(\mathsf{R}_0) = \{aaa, abb, baa\}, \\
		\mathsf{R}_1 & = b_0b_4b_1b_5b_2b_6b_3b_7 \quad \text{ and } \quad \lang(\mathsf{R}_1) = \{aaa, bab, aba\}, \\
		\mathsf{R}_2 & = b_0b_4b_2b_6b_1b_5b_3b_7 \quad \text{ and } \quad \lang(\mathsf{R}_2) = \{aaa, bba, aab\}, \\
	\end{align*}
	and~$\lang(\mathsf{R}_2)=\R{L}$, as desired.
\end{example}
