% sc of reversal
Now we turn to the analyze of the state complexity of this operation. The \dfa for the reversal of a block language $L\subseteq\Sigma^\ell$, with $\ell>0$, is given by reversing each transition on a \dfa for $L$ and then determinising the resulting \nfa. The cost of the determinisation of an $m$-state \nfa for a block language is~$2^{\Theta(\sqrt{m})}$ in size~\cite{KarhOkho:2O14}, so the state complexity of the reversal must also be limited by this bound. 

\begin{corollary}\label{cor:upperscrev}
	Given an $m$-state \dfa for a block language $L$, $2^{O(\sqrt{m})}$ states are sufficient for a \dfa accepting $\R{L}$.
\end{corollary}

In the following, we show that this bound is tight. Let $\ell>0$, $\Sigma=\{a,b\}$, $k=2$, and consider \cref{lem:maxsc}. We define a family of languages, parametrized by $\ell$, that attain the maximal state complexity. For convenience, let $r_\ell=r_{2,\ell}$. Then, consider
	$$\maxmindfa_{\ell} = \{ w_1w_2 \mid w_1\in\Sigma^{\ell-{r_\ell}},\, w_2\in\Sigma^{r_\ell},\, i=\indi(w_1),\, j = \indi(w_2),~\text{and~}  (i+1) \wedge 2^j\neq 0\}\text,$$
where we use the notation~$i\land2^j\neq0$ to indicate that the $j$-th least significant bit of the binary representation of $i$, namely $i_{[2]}$, is $1$. Informally, these languages contain words of size~$\ell$ that can be split in~$w_1$ of size~$\ell-\maxr$ and~$w_2$ of size~$\maxr$, with corresponding indices~$i=\indi(w_1)$ and~$j=\indi(w_2)$, such that the $j$-th least significant bit of~$\bin{(i+1)}$ is~$1$.

\begin{proposition}[\cite{dmpr24a}]\label{lemma:bitmap-of-max}
	The minimal \dfa $A$ accepting the language $\maxmindfa_{\ell}$ has maximal size and $\m=\width(A)=\width(r_{\ell})=\max(2^{\ell-r}, 2^{2^{r-1}}-1)$. Moreover, let
		$$ P_{\m,\maxr} = \prod_{i=1}^{\m} \R{\pad(i_{[2]}, 2^{r_\ell})}\text,$$
	where $\pad(s,t)$ is a function that adds leading zeros to a binary string $s$ until its length equals $t$. Then the bitmap of the language~$\maxmindfa_{\ell}$ is given by
	\begin{align*}
		\bs(\maxmindfa_{\ell}) =
		\begin{cases}
			P_{\m,\maxr},                      & \text{if } \m=2^{\ell-r}, \\
			P_{\m,\maxr} \cdot 0^{2^{r_\ell}}, & \text{if } \m=2^{2^{r-1}}-1.	
		\end{cases}
	\end{align*}
%	Moreover, we have 
