The reversal of $\maxmindfa_{\ell}$, namely $\R{\maxmindfa_{\ell}}$, has a minimal \dfa whose width is at most $2^{r_\ell+1}$.
\begin{lemma} \label{lemma:reversal-maxrank}
	Let $r$ and $r_\ell$ be defined as before for $\ell>0$ and alphabet size $k=2$. A minimal \dfa $\aut{B}$ such that $\width(\aut{B})\leq 2^{r_\ell+1}$ is sufficient to accept the reversal of the language~$\maxmindfa_{\ell}$.
\end{lemma}
\begin{proof}	
	Let $\aut{B}$ be a \dfa such that the last $r_\ell+1$ ranks have maximal width, that is, $2^{\ell-r'}$ states in each rank $r' \in [\ell-r_{\ell}, \ell]$. In particular, the width of the rank $\ell-r_\ell$ is $2^{r_\ell}$. We can order the states in this rank in such way that $\state_j$ is the state whose left language is the reverse of the $j$-th word of $\Sigma^{r_\ell}$, i.e., $\overleftarrow{\lang}(\state_j)=\{\R{w}\}$ where $j=\indi(w)$, for each $j\in[2^{r_\ell}-1]$. 

	 Moreover, let us define the right language of $q_j$ as
		$$\lang_{q_j} = \cset{w\in\Sigma^{\ell-r_\ell}\mid i=\indi(\R{w}), \text{ }(i+1)\wedge2^j\neq 0}\text.$$ 
		Clearly, $\aut{B}$ accepts $\R{\maxmindfa_{\ell}}$. Consider $\aut{B_{q_j}}$, the \dfa $\aut{B}$ with initial state $q_j$, and let us show that $\width(\aut{B_{q_j}}) \leq 2$.

	Let $j\in[2^{r_\ell}-1]$, $r' \in [\ell-r_\ell-1]$, and $\bsr_{r'}$ be the set of factors of size $2^{r'}$ of the bitmap of $\R{\maxmindfa_{\ell}}$. Let $s\in\bsr_{r'}$ and $w_1\in\Sigma^{\ell-r_\ell-r'}$ such that $s$ represents the language $w_1^{-1}\lang_{q_j}$. From the definition of $\lang_{q_j}$, $w_1w_2\in \lang_{q_j}$ if $(i+1)\wedge2^j\neq 0$, where $w_2\in\Sigma^{r'}$ and $i=\indi(\R{w_2}\R{w_1})$. We will now show that the number of states on the rank $r'$ of $\aut{B_{q_j}}$ is bounded by $2$, by arguing that $|\bsr_{r'}| \leq 2$. Consider the following two cases:
		\begin{enumerate}
			\item $j < \ell-r_\ell-r'$: in this case, it is sufficient to check if $(i'+1)\wedge2^j\neq0$, where $i'=\indi(\R{w_1})$, since $|\R{w_1}|=\ell-r_\ell-r'$. Then, either $i'+1$ has its $j$-th bit equal to $1$, which implies that $s=1\cdots 1$, or has not, implying that $s=0\cdots 0$, so $s\notin \bsr_{r'}$. Therefore, $|\bsr_{r'}| = 1$.

			\item $j \ge \ell-r_\ell-r'$: if $w_1\in\Sigma^{\ell-r_\ell-r'}\setminus \{b^{\ell-r_\ell-r'}\}$, the binary representation of $i'+1$, with $i'=\indi(\R{w_1})$, requires at most $\ell-r_\ell-r'$ bits. Then, the $j$-th bit of $i$, corresponds to the ($j-\ell+r_\ell+r'$)-bit of~$w_2$. Hence, $u^{-1}\mathcal{L}_{q_j} = v^{-1}\mathcal{L}_{q_j}$, for all $u, v \in \Sigma^{\ell-r_\ell-r'}\setminus \{b^{\ell-r_\ell-r'}\}$. On the other hand, if $w_1=b^{\ell-r_\ell-r'}$, it results on a different quotient, since $\ell-r_\ell-r'+1$ bits are needed for the binary representation of $i'+1$. Therefore, $|\bsr_{r'}| = 2$.
		\end{enumerate}
	This result implies that~$\width(\aut{B}_{q_j})=2$. As a consequence, the width of the ranks~$r'\in [\ell-r_\ell-1]$ of~$\aut{A}$ are bounded by~$2^{\maxr+1}$, as desired.	
	% Since $\width(\aut{B_{q_j}})=2$, for each $q_j$, the width of $B$ at most doubles by the ranks $r'\in [\ell-r_\ell-1]$. Therefore, we have that $\width(B) \leq 2^{r_\ell+1}$.
\end{proof}

Then, we have the following bound on the state complexity of the reversal of a language.
\begin{theorem}
	Let $L\subseteq\Sigma^\ell$, $\ell>0$, such that $\dsc(L)=m$. Then, $\dsc(\R{L})\in 2^{\Theta(\sqrt{m})}$. 
\end{theorem}
\begin{proof}
	By \cref{cor:upperscrev} we have that $2^{O(\sqrt{m})}$ states are sufficient for a \dfa accepting $\R{L}$. Now, we prove that this cost is necessary in the worst case.

	Let $\aut{A}$ and $\aut{B}$ be the minimal \dfas for $\maxmindfa_{\ell}$ and $\R{\maxmindfa_{\ell}}$ with set of states $Q$ and $P$, respectively. For this proof, assume that~$2^{\ell-r} > 2^{2^{r-1}}-1$, which implies that $r_\ell=r$. A similar proof follows, otherwise.

	 By \cref{lemma:bitmap-of-max}, $\aut{A}$ is of maximal size and its width is exactly~$2^{\ell-r}$.
	 % and, by \cref{lemma:reversal-maxrank}, the width of $\aut{B}$ is bounded by $2^{r_\ell+1}$. Recall also that $\log_2\ell < r < \log_2\ell+2$. 
	 Therefore, the number of states of $\aut{A}$ is
	\begin{align*}
		|Q| & = \sum_{i=0}^{r_\ell-1}(2^{2^i}-1) + \sum_{i=r_\ell}^{\ell}2^{\ell-i} = \sum_{i=0}^{r_\ell-1}2^{2^i} - r_\ell + 2^{\ell-r_\ell+1} - 1 \\
		    & \geq 2^{2^{r_\ell}-1} - (r_\ell+1) \tag*{$2^{\ell-r_\ell+1} > 0$} \\
		    & \geq 2^{2^{\log_2\ell+2}-1} - (\log_2\ell+3) \tag*{$2^{2^{r_\ell}-1} \gg r_\ell$, $r=r_\ell$, and $r<\log_2\ell+2$} \\
			& \geq 2^{4\ell-1} - (\log_2\ell+3) \in 2^{\Omega(\ell)}. \\
	\end{align*}
	By \cref{lemma:reversal-maxrank}, the width of $\aut{B}$ is bounded by $2^{r_\ell+1}$. Moreover, the width of each rank~$i\in[r-1]$ of~$\aut{B}$ is also bounded by~$2^{2^i}-1$, as we have seen in~\cref{lem:maxsc}. Then, let~$r'=\min\{n\in[\ell] \mid 2^{r_\ell+1} \leq 2^{2^n}-1\}$. In particular, we have
	% To estimate the number of states in $\aut{B}$, let $r'=\min\{n\in[\ell] \mid 2^{r_\ell+1} \leq 2^{2^n}-1\}$. In particular, we have
	\begin{align*}
		2^{r_\ell+1} > 2^{2^{r'-1}}-1 & \implies 2^{r_\ell+1} \geq 2^{2^{r'-1}} \implies r_\ell+1 \geq 2^{r'-1} \\
									  & \implies \log_2\ell + 3 \geq 2^{r'-1} \tag*{$r=r_\ell$ and $r<\log_2\ell+2$} \\
									  & \implies r' \leq \log_2(\log_2\ell +3) + 1.
	\end{align*}

	The value of~$r'$ tells us how many ranks in~$\aut{B}$ can achieve the maximal width of~$2^{r_\ell+1}$. Then, the number of states of $\aut{B}$ is bounded by
	\begin{align*}
		|P| & \leq \sum_{i=0}^{r'-1}(2^{2^i}-1) + 2^{r_\ell+1}(\ell-r_\ell-r') + \sum_{i=\ell-r_\ell}^{\ell}2^{\ell-i} \\
			& \leq 2^{2^{r'}} - r' + 2^{r_\ell+1}(\ell-r_\ell-r'+1) - 1 \\ 
			& \leq 2^{2^{\log_2(\log_2\ell +3) + 1}} + 2\cdot2^{r_\ell}(\ell+1) \tag*{$r' \leq \log_2(\log_2\ell +3) + 1$} \\
		    & \leq 2^6\cdot2^{\log_2\ell^2} + 2^3\cdot2^{\log_2\ell}(\ell+1) \tag*{$r=r_\ell$ and $r<\log_2\ell+2$} \\
			& \leq 2^6\ell^2 + 2^3(\ell^2+\ell) = O(\ell^2). \\
	\end{align*}

	Thus, given $L=\R{\maxmindfa_{\ell}}$ with $\dsc(L)=m$, we have that $\dsc(\R{L})=2^{\Omega\left(\sqrt{m}\right)}$, as desired.
\end{proof}

% nsc of reversal
The \nfa for the reversal of a language $L\subseteq\Sigma^\ell$ is given by reversing the transitions on the \nfa for $L$. In fact, the nondeterministic state complexity of the reversal of a finite language coincides with the nondeterministic state complexity of the language, so no better result can be obtained for the block languages.
\begin{theorem}
	Let $L\subseteq\Sigma^\ell$, for some $\ell>0$. Then, $\nsc(\R{L}) =\nsc(L)$.
\end{theorem}
\begin{proof}
	The construction above shows that $\nsc(\R{L}) \leq \nsc(L)$. The following family of languages shows that it is tight. Let $L_\ell = \{a^\ell\}$, with $\ell>0$. We have both that $\nsc(L_\ell) = \ell+1$ and $L_\ell=\R{L_\ell}$.
\end{proof}


\subsection{Word Addition and Word Removal}
% bitmap construction of word operations
Consider a language $L\subseteq\Sigma^\ell$, for some $\ell>0$, over an alphabet of size $k$. The operations of adding or removing a word $w \in \Sigma^\ell$ from the language,  $L\setminus\{w\}$ and $L\cup\{w\}$, respectively, correspond to the not operation on the~$\indi(w)$-th bit of $\bs(L)$. From that observation, we can estimate the state complexity of these operations.

% sc of word operations
\begin{theorem} \label{theorem:sc-word-op}
	Let $L\subseteq \Sigma^\ell$ be a block language with $|\Sigma|=k$ and~$\ell>0$, such that $\dsc(L) = m$. Let~$\oplus \in \{\setminus, \cup\}$, $w \in \Sigma^\ell$, and~$L'=L \oplus \{w\}$. Then, $n - (\ell-1) \leq \dsc(L') \leq m + (\ell-1)$. 
\end{theorem}
\begin{proof}
	Let $\bs(L)$ and $\bs(L')$ be the bitmaps of $L$ and $L'$, respectively. Let us assume that the operation~$\oplus$ results in a different language. Then, the bitmaps~$\bs(L')$ and~$\bs(L)$ differ exactly for one bit. Let $i\in[\ell]$. Then, there is exactly one $j \in [k^{\ell-i}-1]$ such that $s^i_j \neq {t^i_j}$, where $s^i_j$ and ${t^i_j}$ denote the $j$-th bitmap factor of size $k^i$ of $\bs(L)$ and $\bs(L')$, respectively. Also, recall $\bsr(L)_i$ (resp. $\bsr(L')_i$), the set of factors of size $k^i$ of $\bs(L)$ (resp. $\bs(L')$). Then, there are four possible cases:
	\begin{enumerate}
		\item $s^i_j \in \bsr(L')_i$ and $t^i_j \in \bsr(L)_i$: the two sets have the same size;
		\item $s^i_j \in \bsr(L')_i$ and $t^i_j \notin \bsr(L)_i$: $\bsr(L')_i$ has one more element than $\bsr(L)_i$; \label{item:sc-word-op-increase}
		\item $s^i_j \notin \bsr(L')_i$ and $t^i_j \in \bsr(L)_i$: $\bsr(L)_i$ has one more element than $\bsr(L')_i$; \label{item:sc-word-op-decrease}
		\item $s^i_j \notin \bsr(L')_i$ and $t^i_j \notin \bsr(L)_i$: the two sets have the same size.
	\end{enumerate}
Then, the difference on the number of states from a \dfa which accepts the language $L'$ and the \dfa which accepts $L$ is bounded by $\ell-1$, which is the number of ranks neither initial nor final.
\end{proof}

% nsc of word operations
These bounds also extend to the nondeterministic state complexity, as proved in the following result.
\begin{theorem} \label{theorem:nsc-word-op}
	Let $L\subseteq \Sigma^\ell$ be a block language with $|\Sigma|=k$ and~$\ell>0$, such that $\nsc(L) = m$. Let~$\oplus \in \{\setminus, \cup\}$, $w \in \Sigma^\ell$, and~$L'=L \oplus \{w\}$. Then, $m - (\ell-1) \leq\nsc(L') \leq m + (\ell-1)$.
\end{theorem}
\begin{proof}
	Consider the proof of Theorem~\ref{theorem:sc-word-op} and its notation. If the case~\ref{item:sc-word-op-increase} verifies, that is, $|\bsr(L')_i| = |\bsr(L)_i|+1$, then the cover will require at most one more segment to cover the new set. Analogously, the size of the cover for $\bsr(L')_i$ can be smaller by one than the cover for $\bsr(L)_i$, for the case~\ref{item:sc-word-op-decrease}.
\end{proof}

The upper bounds from Theorems~\ref{theorem:sc-word-op} and~\ref{theorem:nsc-word-op} are reached as stated in the following theorem.

\begin{theorem}\label{theorem:witness-word-op}
	The bounds given in \cref{theorem:sc-word-op,theorem:nsc-word-op} are tight.
\end{theorem}
\begin{proof}
	Let $\Sigma = \{a,b\}$ and $\ell>0$. Consider $L_\ell=\{a,b\}^\ell$, whose bitmap is $\bs(L_\ell) = 1^{2^\ell}$. Let $w=a^\ell$. We have that~$\nsc(L_\ell)=\ell+1$ and $\dsc(L_\ell)=1+\nsc(L)=2+\ell$, while~$\dsc(L_\ell\setminus\{w\})=2\ell+1=1+\nsc(L_\ell \setminus\{w\}) $. In the same way it is possible to prove for word addition.
\end{proof}

The family of languages in the previous proof is also a witness for the upper bound of the operation~$\Sigma^\ell\setminus\{w\}$.


\subsection{Intersection} \label{section:intersection}
% bitmap construction of intersection
Let $L_1, L_2 \subseteq \Sigma^\ell$ be two block languages, for some $\ell>0$ and $|\Sigma| = k$, and their respective bitmaps $\bs(L_1)$,~$\bs(L_2)$. The bitmap of the intersection of $L_1$ and $L_2$  is given by $\bs(L_1)\wedge\bs(L_2)$.

% sc of intersection
Now, let~$\aut{A}=\langle Q\cup \{\Omega_1\},\Sigma,\delta_1,\state_0,\{q_f\}\rangle$ and~$\aut{B}=\langle P\cup \{\Omega_2\},\Sigma,\delta_2,p_0,\{p_f\}\rangle$ be the minimal \dfas for $L_1$ and  $L_2$, respectively. For obtaining a \dfa for $L_1\cap L_2$, one can use the standard product construction, and obtain a product automaton  $\aut{C}$. As shown in~\cite{han08} (see Table~\ref{tab:cfin}) the size of $\aut{C}$ is at most $mn-3(m+n)+12$, if $|Q|=m-1$ and $|P|=n-1$. This bound is the result of:
\begin{itemize}
	\item There are no transitions to the initial state neither in $\aut{A}$, $\aut{B}$, nor $\aut{C}$ (this saves $m-1+n-1$ states);
	\item In $\aut{C}$, all pairs of states $(q,\Omega_2)$ and $(\Omega_1,p)$, for $q\in Q$ and $p\in P$, can be merged with $(\Omega_1,\Omega_2)$  (this saves $m-2+n-2$ states);
	\item In $\aut{C}$, all pairs of states $(q,p_f)$ or $(q_f,p)$, for $q\in Q$ and $p\in P$, can be merged with $(q_f,p_f)$ or  $(\Omega_1,\Omega_2)$ (if in general $q_f$ and $p_f$ are the pre-dead states,  this saves $m-3+n-3$ states). 
\end{itemize}

However, for block languages ,pre state can be saved since
% these constraints can be strengthen as one can observe that 
a state~$(q, p)$ of $\aut{C}$ is both accessible from the initial state and leads to the final state if and only if~$\rank(q) = \rank(p)$, for every $q\in Q$, $p\in P$.  

Let $Q_i$ be the set of states in rank $i$ in $\aut{A}$ and $m_i=\width(i)=|Q_i|$, for $i\in [\ell]$. Let $P_i$ be the set of states in rank $i$ in $\aut{B}$ and $n_i=\width(i)=|P_i|$, for  $i\in [\ell]$. Additionally, $m=1+\sum_{i\in[\ell]}m_i$ and $n=1+\sum_{i\in[\ell]}n_i$  since the dead states $\Omega_j$ do not belong to any rank. We have that:

\begin{lemma} \label{lemma:s-intersection-sufficient}
	Given two \dfas $\aut{A}$ and $\aut{B}$ for block languages $L_1$ and $L_2$, respectively, a \dfa with $\sum_{i=0}^{\ell}m_in_i+1$ states is sufficient to recognize the intersection of $L_1$ and $L_2$, where $m_i$ and $n_i$ are the widths of rank $i$ in $\aut{A}$ and $\aut{B}$, respectively, for $i\in [\ell]$.
\end{lemma}
\begin{proof}
	Given the above considerations, the states of the \dfa resulting from trimming $\aut{C}$ are, in the worst-case, $\bigcup_{i\in[\ell]}Q_i\times P_i$ and a single dead state is needed.
\end{proof}

Let us show that this bound is tight for a fixed size of the alphabet, as opposed to the general case of finite languages where a growing alphabet is required~\cite{han08}. Consider the following family of languages, defined over an alphabet $\Sigma$ of size $k$, and let $d>0$ and $x\in\{0,1\}$:
	$$L_{k, d, x} = \cset{a_0\cdots a_{2d-1} \in \Sigma^{2d} \mid \forall i\in[d-1] : i \equiv x \Mod 2 \implies a_i = a_{2d-i}}.$$
	% $$L_{k, d, x} = \cset{a_0\cdots a_{2d-1} \in \Sigma^{2d} \mid \forall i\in[d-1] : i \equiv x \Mod 2 \implies a_i = a_{i+d}}.$$
Informally, it contains the words that can be split into two halves of size $d$, where, if~$x=0$ ($x=1$, resp.), then the symbols in even (odd, resp.) positions of the first half are equal to their 
	symmetric position
	% counterparts 
	in the second half.

\begin{lemma} \label{lemma:intersection-dfa-storage}
	Let~$k\geq2$,~$d\geq 0$, and~$x\in\{0,1\}$. Also, let~$\aut{A}$ be the minimal~DFA for~$L_{k, d, x}$ over a~$k$-letter alphabet~$\Sigma$ and let~$m_i $ be the width of~$\aut{A}$, for~$i\in[2d]$. Then, for~$i\in[d,2d]$ we have:
	\begin{align*}
		m_i =
		\begin{cases}
			k^{\lceil \frac{2d-i}{2} \rceil},   & \text{if } x=0; \\
			k^{\lfloor \frac{2d-i}{2} \rfloor}, & \text{if } x=1, \\
		\end{cases}
	\end{align*}
	and for~$i\in[d]$ we have~$m_i=m_{2d-1}$.
	% Let $k\geq2$, $d>0$, and $x\in\{0,1\}$. Also, let $\aut{A}$ be the minimal \dfa for $L_{k, d, x}$ with set of states $Q=Q_0\cup \ldots\cup Q_{\ell}$, according do the ranks of the states. Then, $|Q_i|=k\cdot|Q_{i+1}|$ if either $x=0$ and $i$ is odd, or $x=1$ and $i$ is even, for every $i\in[d,2d-1]$. Moreover, we have $|Q_i| = |Q_{2d-i}|$, for $i\in[d]$.
\end{lemma}
\begin{proof}
	Let us prove for $x=0$.
	\begin{enumerate}
		\item $(\forall i\in[d,2d]): m_i=k^{\lceil \frac{2d-i}{2} \rceil}$: \\
			Let~$w_1,w_2\in\Sigma^{2d-i}$ such that they differ at least in one even position. Now, let~$w_3 = \sigma^{2(i-d)}\R{w_1}$, for some~$\sigma\in\Sigma$. It is easy to see that~$w_1w_3\in L_{k, d, 0}$ but~$w_2w_3\notin L_{k, d, 0}$, so $w_1$ and $w_2$ have different quotients, and so they have to reach different states. Therefore, the number of states on rank $i$ of $\aut{A}$ is given by~$k^{\lceil \frac{2d-i}{2} \rceil}$, where the exponent is the number of odd integers between $i$ and~$2d-1$.
		\item $(\forall i\in[d]): m_i=m_{2d-i}$: \\
			Let us look at~$\R{\aut{A}}$, the~NFA for~$\R{L_{k,d}}$ given by reversing every transition in~$\aut{A}$ and swapping the initial with the final states. In fact, it is easy to see that~$L_{k,d,x}=\R{L_{k,d,x}}$, hence~$\lang(A)=\lang(\R{\aut{A}})$. In~1, we proved that~$m_j=k^{\lceil \frac{2d-j}{2} \rceil}$, for every rank~$j\in[d,2d]$. The~$i$-th rank in~$\aut{A}$ corresponds to the~$(2d-i)$-th rank in~$\R{\aut{A}}$, so that bound must be preserved.
	\end{enumerate}
	For~$x=1$, the number of states is~$k^{\lfloor \frac{2d-i}{2} \rfloor}$, where the exponent is the number of even integers between~$i$ and~$2d-1$, so the proof is similar.
%	Let us consider $x=0$. Let $i\in[d,2d-1]$ and let us prove that $|Q_i|=k^{\lfloor \frac{2d-i}{2} \rfloor}$. Let $w_1, w_2 \in \Sigma^{2d-i}$ such that they differ at least in one even position. Now, let $w_3 = \sigma^{2(d-i)}w_1$, for some $\sigma \in \Sigma$. It is easy to see that $w_1w_3\in L_{k, d, 0}$ but $w_2w_3\notin L_{k, d, 0}$, so $w_1$ and $w_2$ have different quotients. Therefore, the number of states on rank $i$ of $\aut{A}$ is given by $k^{\lfloor \frac{2d-i}{2} \rfloor}$, where the exponent is the number of odd integers between $i$ and~$2d$.
%	
%	On the other hand, the \dfa must check if the symbols at the even positions of the second half of the word match the counterpart symbols in the first half. Let $w_1, w_2\in\Sigma^{d+i}$, for some $i\in[d]$, such that they differ at least in one even position of the first $d$ symbols. By definition of the language it follows that~$w_1^{-1}L_{k, d, 0} \neq w_2^{-1}L_{k, d, 0}$, so it must hold that $|Q_i| = |Q_{2d-i}|$.
%	
%	For $x=1$, the number of states at rank $i\in[d, 2d-1]$, namely $|Q_i|$, must be at least $k^{\lceil \frac{2d-i}{2} \rceil}$, so the proof is similar.
\end{proof}

Then, we have the following result for the operational state complexity of intersection:
\begin{lemma}\label{lemma:intersection-necessary}
	Let $\aut{A}$ and~$\aut{B}$ be \dfas that accept $L_{k, d, 0}$ and $L_{k, d, 1}$ and $m_i$ and $n_i$ the widths of rank $i$ in $\aut{A}$ and $\aut{B}$, respectively, for $i\in [2d]$ and $d>0$. A \dfa that recognizes the language $L_{k, d, 0}\cap L_{k, d, 1}$ needs~$\sum_{i=0}^{2d}m_in_i+1$ states.
\end{lemma}
\begin{proof}
%	Let $k = |\Sigma|$ and $\aut{A}$ (resp. $\aut{B}$) be the minimal \dfa for $L_{k,d,0}$ (resp. $L_{k,d,1}$) with set of states $Q$ (resp. $P$), where $d=\ell/2$. For the sake of simplicity, we assume that $\ell$ is even. By \cref{lemma:intersection-dfa-storage}, we have~$m_i = k\cdot m_{i+1}$ if $i$ is odd, and~$m_i = m_{i+1}$ otherwise, for $i\in[d, 2d-1]$; and $m_i=m_{2d-i}$, for the remaining ranks $i\in[d]$. Analogously for the language $L_{k,d,1}$, for $i\in[d, 2d-1]$ we  have~$n_i = k\cdot n_{i+1}$ if $i$ is even, and~$n_i = m_{i+1}$ otherwise; and for $i\in[d]$, $n_i=n_{2d-i}$.

	As stated in~\cref{lemma:intersection-dfa-storage}, we have~$m_i=m_{2d-i}=k^{\lceil \frac{2d-i}{2} \rceil}$ and~$n_i=n_{2d-i}=k^{\lfloor \frac{2d-i}{2} \rfloor}$, for~$i\in[d, 2d]$. Moreover, it is easy to see that 
	$$L_{k,d,0}\cap L_{k,d,1} = \{ w\R{w} \mid w\in\Sigma^d\}\text,$$ 
	that is, the set of palindromes of even length. A minimal \dfa~$\aut{C}$ for this language with set of states $S = S_0\cup\ldots\cup S_{\ell}$ must first be able to remember the entire first half of the word, therefore, $|S_i|=k\cdot|S_{i+1}|=k^{2d-i}$ for $i\in[d, 2d-1]$. For the second half, it must check for the repetition of the first, then, $|S_i|=|S_{2d-i}|$, for $i\in[d]$. In fact,
	$$ |S_i| = m_in_i = k^{\lceil \frac{2d-i}{2} \rceil}k^{\lfloor \frac{2d-i}{2} \rfloor}=k^{2d-i}\text,$$	
	as desired.
%	It is easy to see that 
%	$$L_{k,d,0}\cap L_{k,d,1} = \{ w\R{w} \mid w\in\Sigma^d\}\text,$$ 
%	so a minimal \dfa~$\aut{C}$ for this language with set of states $S = S_0\cup\ldots\cup S_{\ell}$ must be able to remember the entire first half of the word, therefore, $|S_i|=k\cdot|S_{i+1}|$ for $i\in[d, 2d-1]$. For the second half, it must check for the repetition of the first, then, $|S_i|=|S_{2d-i}|$, for $i\in[d]$. Hence, $|S_i|=m_in_i$, for $i\in[2d]$.
\end{proof}

From~\cref{lemma:s-intersection-sufficient,lemma:intersection-necessary} we have:
\begin{theorem}\label{theorem:sc-intersection}
	Given two \dfas $\aut{A},\aut{B}$ for block languages $L_1,L_2\subseteq \Sigma^\ell$, for $\ell>0$, $\sum_{i=0}^{\ell}m_in_i +1$  states are necessary and sufficient in the worst-case for a \dfa that accepts the intersection of $L_1$ and $L_2$, where $m_i$ and $n_i$ are the widths of rank $i$ in $\aut{A}$ and $\aut{B}$, respectively, for $i\in [\ell]$.
	\end{theorem}

% nsc of intersection
For the nondeterministic state complexity, the bounds are the same except that the dead state is not considered. In fact, the family witness languages  for the tightness of deterministic state complexity is also a witness for the nondeterministic one.
\begin{theorem}\label{theorem:nsc-intersection}
	Let~$\aut{A}=\langle Q,\Sigma,\delta_1,\state_0,\{q_f\}\rangle$ and~$\aut{B}=\langle P,\Sigma,\delta_2,p_0,\{p_f\}\rangle$ be  minimal \nfas for two block languages $L_1, L_2\subseteq\Sigma^\ell$, respectively, for some $\ell>0$, and such that $|Q| = m$ and $|P| = n$. Let $Q_i$ be the set of states in rank $i$ in $\aut{A}$ and $m_i=\width(i)=|Q_i|$, for $i\in [\ell]$. Let $P_i$ be the set of states in rank $i$ in $\aut{B}$ and $n_i=\width(i)=|P_i|$, for  $i\in [\ell]$. Additionally, $m=\sum_{i\in[\ell]}m_i$ and 
	$n=\sum_{i\in[\ell]}n_i$. 

Then, an \nfa with $\sum_{i=0}^{\ell}m_in_i$ states is sufficient to recognize the intersection of both languages and the bound is tight for $k>1$.
\end{theorem}
\begin{proof} 
	The fact that~$\sum_{i=0}^{\ell}m_in_i$ states are sufficient follows from the previous discussions.
	Moreover,
	this number of states is necessary,
	as can be noticed by considering the languages $L_{k, d, x}$ given above.
	Recall the language $L_{k, d, x}$, for some $k>1$, $d>0$ and $x\in\{0,1\}$.
	In fact,
	it is easy to see that $\dsc(L_{k, d, x})-1 =\nsc(L_{k, d, x})$,
	since the \nfa for $L_{k, d, x}$ must also be able to remember the same information as the \dfa.
	Then,
	if $\aut{A}$ (resp. $\aut{B}$) is a minimal \nfa that recognizes the language~$L_{k, d, 0}$
	(resp. $L_{k, d, 1}$),
	an \nfa that recognizes the intersection of both needs exactly~$\sum_{i=0}^{\ell}n_im_i$ states.
\end{proof}


\subsection{Union}
% bitmap construction of union
Let $L_1, L_2 \subseteq \Sigma^\ell$ be two block languages, for some $\ell>0$ and $|\Sigma| = k$, and their respective bitmaps $\bs(L_1), \bs(L_2)$. The bitmap of the union of~$L_1$ and~$L_2$ is~$\bs(L_1)\vee\bs(L_2)$.

% sc of union
Let~$\aut{A}=\langle Q\cup \{\Omega_1\},\Sigma,\delta_1,\state_0,\{q_f\}\rangle$ and~$\aut{B}=\langle P\cup \{\Omega_2\},\Sigma,\delta_2,p_0,\{p_f\}\rangle$ be the minimal \dfas for $L_1$ and $L_2$, respectively, with $|Q| = m$ and $|P| = n$. Again, let~$\aut{C}$ be the product \dfa of $\aut{A}$ and $\aut{B}$. Because $L_1,L_2$ are finite we know that $m+n$ states can be saved: $m+n-2$ because the initial states are non returning and $2$ more because the final states $(q_f, \Omega_2)$, $(\Omega_1, p_f)$, and $(q_f, p_f)$ can be merged into a single final state. However, again, one only needs to consider pairs of states $(q,p)$ such that $\rank(q) = \rank(p)$, for $q\in Q, p\in P$. Let  $Q_i$ be the set of states in rank $i$ in $\aut{A}$ and $m_i=\width(i)=|Q_i|$, for  $i\in [\ell]$. Let  $P_i$ be the set of states in rank $i$ in $\aut{B}$ and $n_i=\width(i)=|P_i|$, for  $i\in [\ell]$. Additionally, $m=1+\sum_{i\in[\ell]}m_i$ and $n=1+\sum_{i\in[\ell]}n_i$ since the dead states $\Omega_j$ do not belong to any rank. We have that

\begin{lemma}	\label{lemma:sc-union-sufficient}
Given two \dfas $A$ and $B$ for block languages $L_1$ and $L_2$, respectively, a \dfa with 
	$$\sum_{i=1}^{\ell-1}(m_in_i+m_i+n_i)+3$$ 
	states is sufficient to recognize the union of $L_1$ and $L_2$, where $m_i$ and $n_i$ are the widths of rank $i$ in $\aut{A}$ and $\aut{B}$, respectively, for $i\in [\ell]$.
\end{lemma}
\begin{proof}
	Let~$\aut{C}$ be the product automaton from $\aut{A}$ and~$\aut{B}$. As mentioned above, the final states $(q_f, \Omega_2)$, $(\Omega_1, p_f)$ can be merged with $(q_f, p_f)$, and a state $(p,q)$ is only accessible from the initial state if $\rank(p)=\rank(q)$. Therefore, the \dfa resulting from trimming $\aut{C}$ has a single initial state,  a final state and a dead state, and also the states $(Q_i\times P_i) \cup (Q_i\times\{\Omega_2\}) \cup (\{\Omega_1\}\times P_i)$, at each rank $i\in[1, \ell-1]$. Thus, the sufficient  number of states follows.
\end{proof}

In fact, the bound is tight for an alphabet with size at least $3$.

\begin{lemma}\label{lemma:sc-union-necessary}
Given two \dfas $A$ and $B$ for block languages $L_1$ and $L_2$ over $\Sigma^\ell$, respectively, a \dfa with $\sum_{i=1}^{\ell-1}(m_in_i+m_i+n_i)+3$ states is necessary to recognize the union of $L_1$ and $L_2$, where $m_i$ and $n_i$ are the widths of rank $i$ in $\aut{A}$ and $\aut{B}$, respectively, for $i\in [\ell]$ and $|\Sigma| > 2$.
\end{lemma}
\begin{proof}
	Since $\aut{A}$ and $\aut{B}$ are deterministic, $n_{\ell-1}$ and $m_{\ell-1}$, the number of states at rank $\ell-1$ of $\aut{A}$ and $\aut{B}$, respectively, are bounded by $k$ and not equal to $0$. Analogously, the width of the rank $\ell-1$ of the \dfa for the union of $\lang(\aut{A})$ and $\lang(\aut{B})$ is also at most $k$. When $k=2$, it is easy to see that the inequality $0< n_{\ell-1}m_{\ell-1} + n_{\ell-1} +m_{\ell-1} \leq k$ has no solutions.

	Now, consider the languages $L_{1,\ell} = \{a,c\}^\ell$ and $L_{2,\ell} = \{b,c\}^\ell$, and let $\aut{A}$ and $\aut{B}$ be the \dfas that recognize them, respectively, for some $\ell$ and $\Sigma=\{a,b,c\}$. We have that $\dsc(L_{1,\ell}) = \dsc(L_{2,\ell}) = \ell+2$ and $n_i = m_i = 1$, for every $i\in[\ell]$. The minimal \dfa that recognizes the language $L_{1,\ell}\cup L_{2,\ell}$ requires~$3$ states at each rank $i\in[1,\ell-1]$: one state  when some $a$ has already been read, so the word is in $L_{1,\ell}$; one state when some $b$ has already been read, so the word is in $L_{2,\ell}$; and one state for when only $c$'s have been read, so the \dfa still does not know to what particular language it belongs. Then, $\dsc(L_{1,\ell}\cup L_{2,\ell}) = \sum_{i=1}^{\ell-1}(n_im_i+n_i+m_i)+3 = 3\ell$.
\end{proof}

From \cref{lemma:sc-union-sufficient,lemma:sc-union-necessary} we have:

\begin{theorem}\label{theorem:sc-union}
		Given two \dfas $\aut{A},\aut{B}$ for block languages $L_1,L_2\subseteq \Sigma^\ell$, for $\ell >0$, $\sum_{i=1}^{\ell-1}(m_in_i+m_i+n_i)+3$  states are sufficient and necessary, if $\Sigma> 2$,   in the worst-case for a \dfa that accepts  the union  of $L_1$  and~$L_2$, where~$m_i$ and $n_i$ are the widths of rank $i$ in $\aut{A}$ and $\aut{B}$, respectively, for $i\in [\ell]$.
\end{theorem}

% nsc of union
For the nondeterministic state complexity, the upper bound is the same as for finite languages over the same alphabet size.
\begin{theorem}	
	Let $L_1, L_2 \subseteq \Sigma^\ell$ with~$\ell>0$ and~$|\Sigma|=k$, such that $\nsc(L_1) = n$ and $\nsc(L_2) = m$. Then, $\nsc(L_1\cup L_2) \leq n+m-2$, and this bound is reached.
\end{theorem}
\begin{proof}
	Let $L_{1,\ell} = \{a^\ell\}$ and $L_{2,\ell} = \{b^\ell\}$, for some $\ell>0$ and $\Sigma=\{a,b\}$. We have that $\nsc(L_{1,\ell})=\nsc(L_{2,\ell})=\ell+1$ and~$\nsc(L_{1,\ell}\cup L_{2,\ell}) = 2\ell$.
\end{proof}


\subsection{Concatenation}
% bitmap of concatenation
Consider two languages $L_1 \subseteq \Sigma^{\ell_1}$ and $L_2 \subseteq \Sigma^{\ell_2}$, for some $\ell_1, \ell_2 > 0$ and $|\Sigma|=k$, with bitmaps $\bs(L_1)$ and $\bs(L_2)$, respectively. The bitmap for the language $L_1L_2$ is given by replacing each $1$ in $\bs(L_1)$ by $\bs(L_2)$ and each~$0$ by $0^{k^{\ell_2}}$. This ensures that each word of $L_1L_2$ is obtained by concatenating a word of $L_1$ with a word of $L_2$ and for each word obtained in such way the correspondent bit in $\bs(L_1L_2)$ is set to $1$.

% sc of concatenation
The deterministic state complexity of the concatenation for block languages coincides with the one for the finite languages when the first operand, $L_1$, has a single final state in its minimal \dfa. Therefore, we have the following exact upper bound:

\begin{theorem}
Let $L_1\subseteq \Sigma^{\ell_1}$ and $L_2\subseteq \Sigma^{\ell_2}$, for some $\ell_1, \ell_2 > 0$, be two block languages over a $k$-letter alphabet, where $\dsc(L_1)=m$ and $\dsc(L_2)=n$. Then, $\dsc(L_1L_2) = m + n - 2$.
\end{theorem}
\begin{proof}
	Let $\aut{A}$ and $\aut{B}$ be the minimal \dfas for $L_1$ and $L_2$, respectively. Also, let $\aut{C}$ be the minimal \dfa for~$L_1L_2$. Considering the bitmaps for these languages, the width of the rank $i$ of $\aut{C}$ is $|\bsr(L_2)|_i$, if $i\in[\ell_2]$, or is $|\bsr(L_1)|_{i-\ell_2}$, if $i\in[\ell_2+1,\ell_1+\ell_2]$. Then, $\aut{C}$ saves $2$ states by reusing the final state of $\aut{A}$ for the initial state of $\aut{B}$ (alternatively, reusing the initial state of $\aut{B}$ for the final state of $\aut{A}$) and also by eliminating one of the dead states.
\end{proof}

% nsc of concatenation
For the nondeterministic state complexity, the same result is expected, coinciding with the state complexity for the finite languages.
\begin{theorem}
Let $L_1\subseteq \Sigma^{\ell_1}$ and $L_2\subseteq \Sigma^{\ell_2}$, for some $\ell_1, \ell_2 > 0$, be two block languages over a $k$-letter alphabet, where $\nsc(L_1)=m$ and $\nsc(L_2)=n$. Then, $\nsc(L_1L_2) = m + n - 1$.	
\end{theorem}

In fact, any two languages $L_1 \subseteq \Sigma^{\ell_1}$ and $L_2 \subseteq \Sigma^{\ell_2}$ result in a family of witness languages. That is due to the fact that this operation preserves the ranks of the \dfas of the operands. 
\begin{example}\label{example:concatenation}
	Let $L_{1,\ell_1} = \{a^{\ell_1}\}$ and $L_{2,\ell_2} = \{a^{\ell_2}\}$, for $\ell_1, \ell_2>0$ and $\Sigma=\{a\}$. We have that $\dsc(L_{1,\ell_1})=\ell_1+2$, $\dsc(L_2)=\ell_2+2$, and $\dsc(L_{1,\ell_1}L_{2,\ell_2})=\ell_1+\ell_2+2$. We also have  $\nsc(L_{1,\ell_1})=\ell_1+1$, $\nsc(L_{2,\ell_2})=\ell_2+1$, and $\nsc(L_{1,\ell_1}L_{2,\ell_2})=\ell_1+\ell_2+1$.
\end{example}


\subsection{Block Complement}\label{section:block complement}
% bitmap of complement
Consider a language $L \subseteq \Sigma^\ell$, for some $\ell>0$ and alphabet of size $k>0$, and let~$\bs$ be its bitmap. 
Now,
given a block language~$\Sigma^{\ell}$,
we consider block complement language,
namely $\Sigma^{\ell} \setminus L$, also 
denoted by $\overline{L}^\ell$.

Then, the bitmap of the language $\Sigma^\ell \setminus L$, namely~$\overline{\bs}$, is given by flipping every bit of~$\bs$.

% sc of complement
\begin{theorem}\label{theorem:sc-blockcomplement}
	Let $L\subseteq \Sigma^\ell$, with $\ell>0$, be a block language with $|\Sigma|=k$, such that $\dsc(L) = m$. Then, $m - (\ell-1) \leq \dsc(\Sigma^\ell \setminus L) \leq m + (\ell-1)$.
\end{theorem}
\begin{proof}
	The number of states on a rank $i\in[\ell]$ of the minimal \dfa for $\Sigma^\ell \setminus L$ is given by the cardinality of~$\overline{\bsr}_i$, the set of the non-null factors of length $k^i$ on the bitmap~$\overline{\bs}$. If, for some $j\in[k^{\ell-i}-1]$, we have that $s^i_j = 0\cdots0$, which by definition implies that $s^i_j\notin\bsr_i$, then $\overline{s^i_j}=1\cdots1$ and so~$\overline{s^i_j}\in\overline{\bsr}_i$. Moreover, the complement may also occur. Therefore, $\big| |\bsr_i|-|\overline{\bsr}_i| \big| \leq 1$.

	Let $L_\ell=\{a^\ell\}$, for $\ell>0$. As we previously saw on \cref{theorem:witness-word-op}, $\dsc(L)=\ell+1$, and~$\dsc(\Sigma^\ell \setminus L) = 2\ell$.
\end{proof}

% nsc of complement
For the nondeterministic state complexity of the block complement operation, we have that the bound meets the one of the complement from the gmeneral case for finite languages considering the determinization cost of block languages. Also, this bound is asymptotically tight for alphabets of size at least $2$.

\begin{lemma}\label{lemma:nsc-blockcomplement-sufficient} 
	Let $L\subseteq \Sigma^\ell$ be a block language with $|\Sigma|=k$, such that $L$ is accepted by an $m$-state \nfa. Then, $2^{O(\sqrt{m})}$ states are sufficient for an \nfa for $\Sigma^\ell \setminus L$.
\end{lemma}
\begin{proof}
	Let $\aut{A}$ be a \nfa for $L$ with $m$ states. The minimal \dfa $\aut{B}$ for $L$ will have at most $2^{O(\sqrt{m})}$ states~\cite{KarhOkho:2O14}. Furthermore, the minimal \dfa $\aut{C}$ for $\Sigma^\ell \setminus L$ will have at most $\ell+1$ more states then $\aut{B}$, as shown in~\cref{theorem:sc-blockcomplement}. The nondeterministic state complexity is trivially bounded by the deterministic state complexity, so the sufficient number of states follows.
\end{proof}

Consider the following family presented by Karhumäki and Okhotin~\cite{KarhOkho:2O14}:
	$$ L_{k, d} = \cset{w_0\cdots w_{2d-1} \mid \exists i\in[d-1] : w_i = w_{i+d} \in \Sigma \setminus \{\sigma_{k-1}\} }$$ 
	defined over a $k$-ary alphabet $\Sigma = \{\letter_0, \ldots, \letter_{k-1} \}$. Informally, this language contains words that can be split into two halves of size $d$, such that there is at least one position in the first half that matches its counterpart in the second one, and it is different than the ``\emph{prohibited symbol}'' $\sigma_{k-1}$.

\begin{proposition}[\cite{KarhOkho:2O14}] \label{proposition:nsc-complement}
	For each $k\geq2$ and $d\geq2$, the language $L_{k,d}$ is recognized by an \nfa with $(k-1)d^2+2d$ states.
\end{proposition}

\begin{lemma} \label{lemma:nsc-complement}
	For each $k\geq2$ and $d\geq2$, the language~$\overline{L}_{k,d}^{2d}$ defined over a $k$-letter alphabet~$\Sigma$ requires at least $k^d$ states on the $d$-th rank.
\end{lemma}
\begin{proof}
	First, notice that~$\overline{L}_{k,d}^{2d}$ is the block complement of the language  $\overline{L}_{k,d}$ defined above, formally
	$$ \overline{L}_{k,d}^{2d} = \cset{ w_0\cdots w_{2d-1} \mid \forall i\in[d-1]: w_i \neq w_{i+d} \text{ or }  w_i = \sigma_{k-1} }\text.$$
	Let $w_1$ and $w_2$ be two words in $\Sigma^d$ such that~$a$ and~$b$ are the~$i$-th symbols of~$w_1$ and~$w_2$, respectively, with~$a\neq b$ and~$i\in[d]$. If~$a=\sigma_{k-1}$ then, with~$w_3=\sigma_{k-1}^{i-1}\,b\,\sigma_{k-1}^{d-i}$, we have~$w_1w_3\in\overline{L}_{k,d}^{2d}$ but~$w_2w_3\notin\overline{L}_{k,d}^{2d}$. If~$b=\sigma_{k-1}$ then, with~$w_3=\sigma_{k-1}^{i-1}\,a\,\sigma_{k-1}^{d-i}$, we have~$w_1w_3\notin\overline{L}_{k,d}^{2d}$ but~$w_2w_3\in\overline{L}_{k,d}^{2d}$. As a consequence,~$w_1^{-1}\overline{L}_{k,d}^{2d} \neq w_2^{-1}\overline{L}_{k,d}^{2d}$. Therefore, one state in rank~$d$ is needed for each word in~$\Sigma^d$.

%	Let $u$ and $v$ be two distinct words in $\Sigma^d$. It is easy to see that~$u^{-1}\overline{L}_{k,d}^{2d} \neq v^{-1}\overline{L}_{k,d}^{2d}$. Moreover, there is at least a word~$w\in u^{-1}\overline{L}_{k,d}^{2d}$ such that~$w\notin v^{-1}\overline{L}_{k,d}^{2d}$, and vice versa, thus neither set is a subset of the other. As a consequence, one state in rank~$d$ is needed for each word in~$\Sigma^d$.

%	and each set has exactly one element. Then, one state on rank~$d$ is needed for each word in $\Sigma^d$.
\end{proof}

With these results, it is possible to determine that the nondeterministic state complexity for the complement operation given in \cref{lemma:nsc-blockcomplement-sufficient} is tight.

\begin{theorem}\label{theorem:nsc-complement}
	Let $m\geq2$ and $\Sigma$ an alphabet of size $k\geq2$. Then, there exists a language $L\subseteq\Sigma^\ell$, for some~$\ell>0$, such that $\nsc(L)=m$ and $\nsc(\Sigma^{\ell} \setminus L)=2^{\Omega\left(\sqrt{m}\right)}$. 
\end{theorem}
\begin{proof}
	Consider $d$ as the largest integer for which $(k-1)d^2+2d\leq m$. Following the work in~\cite{KarhOkho:2O14}, we have that
	$$d =  \left\lfloor \sqrt{\frac{m}{k-1} + \frac{1}{(k-1)^2}} - \frac{1}{k-1} \right\rfloor\text.$$
	Then, $L_{k,d}$ is a language recognized by an $m$-state \nfa, while every \nfa for $\overline{L}_{k,d}^\ell$ requires, by Lemma~\ref{lemma:nsc-complement}, at least
	$$k^d = k^{\left\lfloor \sqrt{\frac{m}{k-1} + \frac{1}{(k-1)^2}} - \frac{1}{k-1} \right\rfloor} \geq k^{\sqrt{\frac{m}{k-1}}-2} =2^{\Omega(\sqrt{m})}$$
	states, as required.
\end{proof}


\subsection{Kleene Star and Plus}\label{section:starandplus}
% construction of star
Let $L\subseteq\Sigma^\ell$, for some $\ell>0$ and $\bs$ its bitmap. From $\bs$ one can obtain the minimal \dfa for $L$, namely $\aut{A}=\langle Q,\Sigma,\delta_0,\state_0,\{\state_f\}\rangle$.

 A \dfa $\aut{B}=\langle Q\setminus \{ q_f\},\Sigma,\delta_1,\state_0,\{\state_0\}\rangle$ recognizes the language $L^\star$ if $\delta_1(\state,\letter)=q_0$, for all $\state\in Q$ such that $\rank(\state)=1$ and $\letter\in\Sigma$, and $\delta_1(\state,\letter)=\delta(\state,\letter)$, for the remaining pairs $(\state, \letter)\in Q\times\Sigma$. That is, the \dfa for $L^\star$ is given by substituting  all the transitions with final state as the target state to transitions to the initial state. The same applies for the \nfa for $L^\star$, as the following theorem states.

% sc and nsc of star
\begin{theorem}
	Let $L\subseteq \Sigma^\ell$, with $\ell>0$, be a block language with $\dsc(L) = n$ and $\nsc(L) = m$. Then, $\dsc(L^\star) = n-1$ and $\nsc(L^\star) = m-1$.
\end{theorem}

% construction of plus
Moreover, a \dfa $\aut{C}=\langle Q,\Sigma,\delta_2,\state_0,\{\state_f\}\rangle$ recognizes the language $L^+$ if $\delta_2(q_f, \letter) = \delta_0(q_0, \letter)$, for $\letter\in\Sigma$. Again, the \nfa for $L^+$ is given by applying the same changes to the minimal \nfa for $L$. And the witness languages coincide with the ones for finite languages, namely 
$L_{\ell} = \{a^{\ell}\}$ , for $\ell> 0$.
% sc and nsc of plus
\begin{theorem}
	Let $L\subseteq \Sigma^\ell$, with $\ell>0$. Then, $\dsc(L^+) = \dsc(L)$ and $\nsc(L^+) =\nsc(L)$.
\end{theorem}



\section{Conclusions} \label{section:conclusions}
The complexities obtained for operations on block languages are summarized in \cref{tab:cblock}. One can compare these results with the ones for finite languages summarized in \cref{tab:cfin}. For the deterministic state complexity, the bounds for Boolean operations on block languages are given using the rank widths and are smaller than the ones for finite languages. It would be interesting to express them as a function of the number of states of the operands (as it is usually done). Moreover, those bounds could be obtained from a direct construction of the minimal \dfa for the resulting language considering the bitmaps of the operands. Note that bitwise Boolean operations can be performed to obtain the bitmap factors (i.e., states) in each rank of the resulting \dfa. This study will be interesting to pursue in future work. For concatenation and Kleene star the bounds correspond to special cases of the ones for finite languages. Finally, for reversal the results are analogous to the ones for finite languages, but here considering the bounds known for the determinization of block languages. The results for nondeterministic state complexity meet the values known for finite languages except for intersection and the specific operations for block languages (block complement, word addition, and word removal).

