\title{Ray Antenna Array: A Novel Cost-Effective Multi-Antenna Architecture for Enhanced Wireless Communication}
\author{
	\IEEEauthorblockN{
		Zhenjun Dong\IEEEauthorrefmark{1},
		Zhiwen Zhou\IEEEauthorrefmark{1},
		Yong Zeng\IEEEauthorrefmark{1}\IEEEauthorrefmark{2},\\
