the proposed RAA can significantly reduce the hardware cost, which accounts for only 6.9\textperthousand$ $ of that of the HBF architecture. % amounting to only 6.9\textperthousand$ $ of the HBF architecture.

\section{Joint RAA Beamforming and Ray Selection}

As shown in Fig. 2, the uplink RAA-based multi-user communications are considered, where a base station (BS) equipped with the proposed RAA serves $K$ single-antenna users.
The resulting signal of user $k$ at the BS is expressed as
\begin{equation}\label{channel model}
    y_k=\vec{f}_k^H \vec{S}\vec{h}_ks_k+\vec{f}_k^H \vec{S}\sum\nolimits_{i\neq k}\vec{h}_is_i
    +\vec{f}_k^H \vec{S}\vec{z}',
\end{equation}
where $\vec{f}_k\in \mathbb{C}^{N_{\text{RF}} \times 1}$ is the baseband beamforming of user $k$;
$\vec{h}_k\in\mathbb{C}^{N\times 1}$ is the effective channel vector for user $k$, modeled as
\begin{equation}\label{h_eff}
\vec{h}_k=\sum\nolimits_{l =1}^{L_k}\alpha_{k,l} \vec{r}(\theta_{k,l}),
\end{equation}
where $L_k$ is the number of multipath components (MPCs) for user $k$,
$\alpha_{k,l}$ is the complex gain of the $l$th MPC for user $k$, %satisfying $\sum_{l=1}^{L_k}|\alpha_{k,l}|^2=1$,
and
 $\theta_{k,l}\in \left[-\eta_{\text{max}},\eta_{\text{max}}\right]$ is the AoA of the $l$th MPC for user $k$;
 $s_k$ is the information-bearing symbol of user $k$ with $\mathbb{E}[|s_k|^2]=P_t$,  and $P_t$ is the transmit power;
 %Then, the received signal vector of $K$ users at the BS, denoted by $\vec{y}=[y_1,...,y_K]\in\mathbb{C}^{N\times 1}$ is
%\begin{equation}\label{channel model2}
 %   \vec{y}=\vec{F}^{\text{BB}} \vec{F}^{\text{AB}}\vec{H}^{\text{eff}}
  %  \vec{s}+\vec{F}^{\text{BB}} \vec{F}^{\text{AB}}\vec{z}^{\text{eff}},
%\end{equation}
%where $\vec{F}^{\text{BB}}=\left[\vec{f}_1^{\text{BB}},...,\vec{f}_K^{\text{BB}}\right]\in \mathbb{C}^{K\times N_{\text{RF}}}$ is the digital combining matrix, $\vec{H}^{\text{eff}}=\left[\vec{h}_1^{\text{eff}},...,\vec{h}_K^{\text{eff}}\right]\in \mathbb{C}^{N\times K}$ is the effective channel matrix, and $\vec{s}=[s_1,...,s_K]\in \mathbb{C}^{K\times 1}$ is the transmit symbol vector of $K$ users.
%The total power constraint of the hybrid combining matrix is enforced by $\|\vec{F}^{\text{DB}}\vec{F}^{\text{AB}}\|_F^2=N_s$. 
 and $\vec{z}'=[\vec{z}_n^T\vec{1}_{M\times 1}]_{n\in\mathcal{N}}\in \mathbb{C}^{N\times 1}$ is the effective noise vector, with $\vec{z}_n\in \mathbb{C}^{M\times 1}\sim N_{\mathbb{C}}\left(0,\sigma^2\vec{I}_{M}\right)$ being the noise at sULA $n$ following independent and identically distributed (i.i.d.) circularly symmetric complex gaussian (CSCG) distribution with variance $\sigma^2$, thereby  $\vec{z}' \sim N_{\mathbb{C}}(0,M\sigma^2\vec{I}_{N})$.
Thus, the signal-to-interference plus noise ratio (SINR) of user $k$ is
\begin{equation}\label{channel model3}
     \text{SINR}_k=\frac{\bar{P_t}\left|\vec{f}_k^H \vec{S}\vec{h}_k
    \right|^2}{\bar{P_t}\sum_{i\neq k}\left|\vec{f}_k^H \vec{S}\vec{h}_i
    \right|^2+M\|\vec{f}_k^H \vec{S}\|^2},
\end{equation}
where $\bar{P_t}=\frac{P_t}{\sigma^2}$ represents the transmit signal-to-noise ratio (SNR).
In particular, the SNR for the single-user scenario is
 \begin{equation}\label{SNR}
\text{SNR}=\bar{P_t}\left|\vec{f}^H\vec{S}\vec{h}\right|^2/(M\vec{f}^H \vec{S}\vec{S}^H \vec{f})\triangleq\bar{P_t}\left|\vec{f}^H\vec{S}\vec{h}\right|^2/(M\vec{f}^H  \vec{f}),
 \end{equation}
 %In order to maximize SNR in (\ref{SNR}), the combining design problem of $\vec{f}^{\text{BB}}$ and $\vec{F}^{\text{AB}}$ is described as
%\begin{equation}\label{SNR_max}
%\begin{aligned}
 %  \vec{f}^{\text{BB}}_{\text{opt}},\vec{F}^{\text{AB}}_{\text{opt}} =&\underset{\vec{f}^{\text{BB}},\vec{F}^{\text{AB}}}{\text{argmax}} \quad \text{SNR}\\
 %  \text{s.t.}:&\enspace\left\|\vec{f}_i^{\text{AB}}\right\|_0=1,\enspace 1\leq i\leq N_{\text{RF}}.
 %  \end{aligned}
%\end{equation}
where ``$\triangleq$" follows from $[\vec{S}]_{i,:}[\vec{S}]_{i,:}^H=1$ and $[\vec{S}]_{i,:}[\vec{S}]_{j,:}^H=0$, $\forall j\neq i$, leading to $\vec{S}\vec{S}^H=\vec{I}_{N_{\text{RF}}}$
. For any given ray selection matrix $\vec{S}$, the optimal baseband beamforming is the
%The maximum SNR in (\ref{SNR}) can be obtained by designing the RSN to select the $N_{\text{RF}}$ elements with the strongest amplitude from $\vec{h}$, and designing the digital combining as the
maximum ratio combining (MRC), i.e., $\vec{f}=\vec{S}\vec{h}$.
Thus, the SNR can be expressed as a function of the ray selection matrix $\vec{S}$ as
 \begin{equation}\label{SNR2}
\text{SNR}(\vec{S})=\bar{P_t}\|\vec{S}\vec{h}\|^2/M.
 \end{equation}

 It is observed from (\ref{SNR2}) that to maximize the SNR in a single-user RAA system, the optimal $\vec{S}$ corresponds to selecting the $N_{\text{RF}}$ elements of $\mathbf h$ with the largest magnitudes.
In particular, considering a single-path case, we have $h_n=\alpha_l\sqrt{G(0)}M$ when the path is perpendicular to sULA $n$, i.e., $\theta=\eta_n$. Thus, the resulting maximum SNR in (\ref{SNR2}) is $\bar{P_t}|\alpha_l|^2G(0)M$, which increases with $M$. %This indicates that the proposed RAA can achieve performance comparable to that of the conventional HBF, without any analog or digital beamforming.
Similar conclusions can be drawn for the multipath case.
% such that the  proposed RAA can obtain $M$-times array gain.

For the more general multi-user RAA system, the joint design of $\vec{F}=\left[\vec{f}_k\right]_{1\leq k \leq K}\in \mathbb{C}^{ N_{\text{RF}}\times K}$ and $\vec{S}$ is formulated as an optimization problem to maximize the sum rate
\vspace{-0.2cm}
\begin{equation}\label{channel model4}
\begin{aligned}
   \underset{\vec{F},\vec{S}}{\text{max}}& \quad R_{\text{sum}}=\sum\nolimits_{k=1}^{K}\text{log}_2(1+\text{SINR}_k)\\
   \text{s.t.}& \quad(C1):
               \enspace\vec{S}\in \{0,1\}^{N_{\text{RF}}\times N},\\
               &\quad(C2):\enspace\left\|[\vec{S}]_{i,:}\right\|_0=1,\enspace 1\leq i\leq N_{\text{RF}},\\
               &\quad(C3):\enspace\left\|[\vec{S}]_{:,n}\right\|_0\leq 1,\enspace 1\leq n\leq N.\\
   \end{aligned}
\end{equation}

Problem (\ref{channel model4}) is challenging to solve directly due to the binary constraint in (C1) and the non-convex $l_0$-norm in (C2) and (C3).
In addition, the digital beamforming $\vec{F}$ and ray selection $\vec{S}$ are coupled.
It is worth noting that if the exhaustive search is applied to select the $N_{\text{RF}}$ best rays from a total of $N$, it will result in $\tbinom{N}{N_{\text{RF}}}$ candidate solutions, leading to prohibitive complexity when $N$ and ${N_{\text{RF}}}$ are large.
Therefore, a greedy scheme is proposed to reduce the computational complexity to $O(NN_{\text{RF}})$.

Note that for any given ray selection matrix $\vec{S}$, it follows from (\ref{channel model3}) that the optimal baseband beamforming for sum rate maximization is given by the minimum mean square error (MMSE) beamforming, which is expressed as
$\vec{f}_k=\vec{C}_k^{-1}\vec{S}\vec{h}_k$ with $\vec{C}_k\triangleq\vec{S} \bigl(\sum_{i \neq k}\vec{h}_i\vec{h}_i^H+M/\bar{P_t}\vec{I}_N\bigl)\vec{S}^H$ being the interference-plus-noise covariance matrix, $1\leq k\leq K$.
%where $\vec{C}\triangleq\vec{S} \left(\sum_{i\ne  k}\vec{h}_i\vec{h}_i^H+\frac{M}{\bar{P_t}}\vec{I}_M\right)\vec{S}^H$ denotes the interference-plus-noise covariance matrix.
By substituting the matrices $\vec{S}$ and $\vec{F}$ into (\ref{channel model4}), the resulting maximum sum rate under the set $\Omega$ is
\vspace{-0.05cm}
\begin{equation}\label{channel model5}
    R_{\text{sum}}(\Omega)=\sum\nolimits_{k=1 }^{K}\text{log}_2\bigl(1+(\vec{S}\vec{h}_k)^H \vec{C}_k^{-1}\vec{S}\vec{h}_k\bigl).
\end{equation}
%For the sake of simplicity, the scenario of NRF = U will be firstly explained as follows.

In the proposed greedy scheme, one ray of the RAA is selected at each step to maximize the sum rate.
At the $i$-th step, the optimal element $n^{(i)}$ is determined based on $n^{(i)}=\underset{n}{\text{argmax}} \quad R_{\text{sum}}(\Omega^{(i-1)}\cup n)$,
and the resulting sum rate is $R_{\text{sum}}(\Omega^{(i)})$ with $\Omega^{(i)}=\Omega^{(i-1)}\cup n^{(i)}$. This process continues until $N_{\text{RF}}$ sULAs are selected.
The main procedure of the greedy scheme is summarized in Algorithm 1.
\vspace{-0.1cm}
\begin{algorithm}[htb]
\caption{The proposed greedy scheme for RAA ray selection}
\label{alg:Framwork}
\begin{algorithmic}[1] %这个1 表示每一行都显示数字
\STATE Initialize $\Omega^{(0)}=\emptyset$ and $\mathcal{N}=\{1,..,N\}$.\\ %算法的输入参数：Input
\STATE \textbf{for} $i=1:N_{\text{RF}}$ \textbf{do}\\ %算法的输出：Output
\STATE  \quad Calculate $n^{(i)}=\underset{n\in \mathcal{N}}{\text{argmax}} \quad R_{\text{sum}}(\Omega^{(i-1)}\cup n)$;
\STATE \quad Update $\Omega^{(i)}=\Omega^{(i-1)}\cup n$ and $\mathcal{N}=\mathcal{N}\backslash n^{(i)}$;
\STATE \textbf{end for}
\STATE \textbf{Output:} The set of selected $N_{\text{RF}}$ elements $\Omega^{(N_{\text{RF}})}$.
\end{algorithmic}
\end{algorithm}

