\begin{restatable}{theorem}{ReachEquivalentMinLocalGlobal}\label{theorem:ReachEquivalentMinLocalGlobal}
If $\Su$ is a  compact subset of $\R^d$, then:
\[
\rch( \Su )= \min ( \rch_{glob.}(\Su), \rch_{loc.}(\Su) )
\]
