\begin{lemma}[Angle with tangent space, Theorem 4.8(7)  of \cite{Federer}] \label{Lem:distanceToTangent} 
Suppose that $\Su$ is a set positive reach $\rch(\Su)$.
Let $p,q \in \Su \subset \mathbb{R}^d$ such that $|p-q| < \rch(\Su)$. We have 
\begin{align} 
\sin \angle (q-p, \Tan(p, \Su) ) \leq \frac{|p-q|}{2\,  \rch (\Su)}.
\label{AngleSegmentToT}
\end{align} 
