Moreover, a variant of the previous lemma characterizes the reach for arbitrary closed sets, that is:
\begin{lemma}[Distance to tangent space characterizes the reach, Theorem 4.18  of \cite{Federer}] 
\label{Lem:distanceToTangentCharacter} %{\color{red} multiple defined label resolved}
For a closed subset $\Su$ of Euclidean space $\mathbb{E} = \R^d$, one has:
\begin{equation}\label{TangentSpaceLine_2}
\rch(\Su) = \inf_{\myatop{p,q\in \Su}{p\neq q}} \frac{|p-q|^2}{2 d_{\mathbb{E} } (q ,\: p \: + \Tan(p, \M) ) } 
%{p,q\in \Su}\atop {p\neq q}
\end{equation}
\end{lemma}


\begin{lemma}[Theorem 4.8 (4) of \cite{Federer}]\label{Fed4.8.4}
$\pi_\Su$ is continuous on $\mathbb{R}^d  \setminus \ax(\Su)$.
\end{lemma}
In fact the following lemma strengthens the previous. 

\begin{lemma}[Theorem 4.8 (8) of \cite{Federer}]\label{Fed4.8.8}
If $x,y \in \mathbb{R}^d$, and $\max \{|x - \pi_{\Su}(x)| , |y - \pi_{\Su}(y)|\} = \mu \leq \rch(\Su)$, then
\begin{align} 
|\pi_\Su(x)- \pi_{\Su}(y) |\leq \frac{ \rch(\Su)}{ \rch(\Su)- \mu} |x-y| 
\nonumber
\end{align} 
\end{lemma}

\begin{lemma}[Theorem 4.8 (12) of \cite{Federer}]\label{Fed4.8.12}
If $p \in \Su$ and $\lfs (p)> \rho > 0 $, then 
\begin{align}
\Nor ( p,\Su) = \{ \lambda v \mid \lambda\geq 0 , | v| = \rho ,  \pi_\Su (p+v) =p\} .
\nonumber
\end{align}
$\Tan(p,\Su)$ is the convex cone dual to $\Nor(p,\Su)$, and 
\begin{align}
\lim_{t \to 0^+} t^{-1} d_\M (p +t u) =0,
\nonumber
\end{align}
for $u\in T(p,\Su)$ 
\end{lemma}

%\Andre{Is next lemma used somewhere ?} {\color{red} Yes in the proof of Lemma \ref{lemma:embeddedManifoldPositiveReachThenTangentSpaceIsVectorial}. }
\begin{lemma}[Remark 4.15 (1) of \cite{Federer}]\label{Fed4.15.1}
If $p \in \Su$ and $\lfs (p)> \rho > 0 $, then $\Su \cap B(p, \rho)$ is contractible.
\end{lemma}

