\[
\rch_{loc.}(p, \Su) = \lim_{\substack{\rho \rightarrow 0 \\ \rho >0}} \: \inf_{q\in \Su \cap B^{\circ}(p, \rho)} \:  \rch_{loc.}(q, \Su).
