\begin{proof}[Proof of Lemma \ref{lemma:NorIsSemiContinuous}]
Take $\rho$ such that $0< \rho < \rch(\Su)$ and denote by $\Su^{\partial \oplus \rho}$ 
%{\color{red} I am not sure if the notation $\uparrow$ is optimal, I was thinking of $\partial \oplus$, but this is a bit longer}
%\Andre{I tend to agree with you... I used  $\uparrow$ without much enthusiasm. $\partial \oplus$ is not wonderful, but still better.}
 the boundary of the $\rho$-offset of $\Su$, in other words,
\[
\Su^{\partial \oplus \rho} \defunder{=}  \{x \in \R^d \mid \: d(x, \Su) = \rho \}.
\]
For $p \in \Su$, we write $N(p, \Su, \rho)$ for the set of points of $\Su^{\partial \oplus \rho}$ whose projection is $p$, that is
\[
N(p, \Su, \rho) \defunder{=} \{  q \in \Su^{\partial \oplus \rho}\mid \:  \pi_{\Su}(q) = p \}. 
\]
Lemma \ref{Fed4.8.12} yields that if $p \in \Su$, then
\begin{equation}\label{equation:NormalConeFromPointsAtDistanceRho}
\Nor(p, \Su) = \{ \lambda (q - p) \mid \: \lambda \geq 0, \: q \in N(p, \Su, \rho)  \}.
\end{equation}
For $\eta >0$ we denote by $N(p, \Su, \rho)^\eta$  the open offset of $N(p, \Su, \rho)$ in $\Su^{\partial \oplus \rho}$, that is 
\[
N(p, \Su, \rho)^\eta \defunder{=} \Big\{ q \in \Su^{\partial \oplus \rho}, d\big(q, N(p, \Su, \rho) \big) < \eta \Big\}. 
\]
For any integer $j \geq 1$,  the set
\[
\Su^{\partial \oplus \rho}  \cap \pi_{\Su}^{-1} \Big( B(p, 1/j) \cap \Su \Big)
\]
is compact, being bounded and the inverse image of a closed set by the continuous map $\pi_{\Su}$.
Because $\Su^{\partial \oplus \rho}  \setminus N(p, \Su, \rho)^\eta$ is a closed set, the set
\begin{align} 
K_j &\defunder{=} \Su^{\partial \oplus \rho}  \cap \pi_{\Su}^{-1} \Big( B(p, 1/j) \cap \Su \Big) \cap \big( \Su^{\partial \oplus \rho}  \setminus N(p, \Su, \rho)^\eta \big)
\nonumber 
\\ 
&=  \big( \Su^{\partial \oplus \rho}  \setminus N(p, \Su, \rho)^\eta \big)  \cap \pi_{\Su}^{-1} \Big( B(p, 1/j) \cap \Su \Big) 
\nonumber 
\end{align}
is compact, but may be empty.
We have that 
\[
\bigcap_{j\geq 1} \pi_{\Su}^{-1} \Big( B(p, 1/j) \cap \Su \Big)= \pi_{\Su}^{-1} \big( \{ p \} \big) ,
\]
because if $ a \notin \pi_{\Su}^{-1} \big( \{ p \} \big)$, then $\pi_{\Su} (a)= q \neq p$ and thus $a \notin \bigcap_{j\geq 1} \pi_{\Su}^{-1} \Big( B(p, 1/j) \cap \Su \Big)$ for some $j$.
Hence,   since 
\[
\bigcap_{j\geq 1} K_j  = \Su^{\partial \oplus \rho}  \cap \pi_{\Su}^{-1} \big( \{ p \} \big) \cap \big( \Su^{\partial \oplus \rho}  \setminus N(p, \Su, \rho)^\eta \big) = 
N(p, \Su, \rho) \cap \big( \Su^{\partial \oplus \rho}  \setminus N(p, \Su, \rho)^\eta \big) = \emptyset,
\]
we have that $\big(K_j\big)_{(j \geq 1)}$ is a nested (in inverse order) sequence of compact sets whose intersection is empty. Therefore, there is some 
integer number $n \geq 1$ such that $K_n = \emptyset$, such that
\[
\Su^{\partial \oplus \rho}  \cap \pi_{\Su}^{-1} \Big( B(p, 1/n) \cap \Su \Big) \subset  N(p, \Su, \rho)^\eta.
\]
We note that such an $n$ exists for any $\eta >0$. This implies that for any $\eta$ such that $0< \eta <  \rho \sin  \frac{\epsilon}{2}$, there exists an $n$ large enough such that both:
\begin{equation} \label{equation:NormalConeConditionOnP}
\frac{1}{n} < \frac{1}{2}  \rho \sin \epsilon
\end{equation}
and
\begin{equation} %\label{equation:NormalConeConditionOnQ}
\Su^{\partial \oplus \rho}  \cap \pi_{\Su}^{-1} \big( B(p, 1/n) \cap \Su \big) \subset  N(p, \Su, \rho)^{\rho \sin  \frac{\epsilon}{2} }. 
\nonumber
\end{equation} 
Using this $n$ we pick $\alpha = \frac{1}{n}$, and we claim that this $\alpha$ satisfies the assertion in the lemma.
Indeed, if $p' \in \Su \cap B(p, \alpha)$, then $N(p', \Su, \rho) \subset N(p, \Su, \rho)^{\rho \sin  \frac{\epsilon}{2} }$. Hence by definition,
 if $q' \in N(p', \Su, \rho)$, then there exists a
 $q \in N(p, \Su, \rho)$ such that $d(q, q') < \rho \sin  \frac{\epsilon}{2} $,  while by \eqref{equation:NormalConeConditionOnP}, 
$d(p,p') < \rho \sin  \frac{\epsilon}{2} $.
Since $| q-p |= | q' - p'| = \rho$ and $|p-p'|, |q-q'| < \rho \sin  \frac{\epsilon}{2}$, we get
\[
| (q-p) - (q'-p')| < 2 \rho \sin  \frac{\epsilon}{2},
\]
so that
\[
\angle (q'-p', q - p) < \epsilon. 
\]
This holds for any    $q' \in N(p', \Su, \rho)$ and since  $q \in N(p, \Su, \rho)$,
the claim is proved, thanks to \eqref{equation:NormalConeFromPointsAtDistanceRho}.
\end{proof}


\begin{proof}[Proof of Lemma \ref{lemma:anglebetweenKVectorSpacesIsSymmetric}]
If $A=B$ the statement is trivially true.
If $A\neq B$, the bisector of $A$ and $B$ contains at least one hyperplane $P$ and $B$ is the image of $A$ by the isometric mirror symmetry with respect to $P$. 
\end{proof}

\begin{proof}[Proof of Lemma \ref{lemma:embeddedManifoldPositiveReachThenC1Embedded}]
Lemma \ref{lemma:embeddedManifoldPositiveReachThenTangentSpaceIsVectorial}
says that $\Tan(q, \M)$ is a $n$-dimensional vector space for any $q \in \M$.

Regarding $\Tan(q, \M)$ as an element of the Grassmannian $\Grass(n, \R^d)$, 
Lemmas \ref{lemma:NorIsSemiContinuous} and \ref{lemma:anglebetweenKVectorSpacesIsSymmetric} give
 that the map defined from $\M$ to  $\Grass(n, \R^d)$ by  $q \mapsto \Tan(q, \M)$
is continuous. 
%{\color{red} I would like to move this up, perhaps even into the introduction.} Here $\Grass(n, \R^d)$ is equipped with the angle metric
%defined for $A,B \in \Grass(n, \R^d)$ by (see also Lemma \ref{lemma:anglebetweenKVectorSpacesIsSymmetric}):
%\begin{equation}\label{equation:DefinitionAngleVectorSpaces}
%\angle A, B \defunder{=} \max_{a\in A\setminus \{0\}} \min_{b \in B \setminus \{0\}}
 %\angle a,b = \max_{b \in B\setminus \{0\}} \min_{a \in A \setminus \{0\}} \angle a,b .
%\end{equation}
It follows that, for $p\in \M$, there is some $\epsilon$, with $0< \epsilon < \rch(\M) /2$, such that
 \begin{equation}\label{equation:SmallAngleBetweenTangentSapces}
\forall q \in \M \cap B(p, \epsilon), \angle \Tan(q, \M) , \Tan(p,\M) < \pi/4.
 \end{equation}
We  claim that for this $\epsilon$, the restriction to $\M \cap B(p, \epsilon)$ of the orthogonal projection on $p+\Tan(p, \M)$ is injective.

Indeed, assume (to derive a contradiction) that there exist $q_1,q_2 \in \M \cap B(p, \epsilon)$ 
such that $q_1 \neq q_2$ and $\pi_{p+\Tan(p, \M)} (q_1) = \pi_{p+\Tan(p, \M)} (q_2)$.
Then, because $|q_2-q_1| < \rch(\M)$, 
%\Andre{
inequality \eqref{AngleSegmentToT} from Lemma \ref{Lem:distanceToTangent} yields that
$\sin \angle  (q_1- q_2, \Tan(q_1, \M) ) \leq \frac{1}{2}$. %so that,
Combining this with \eqref{equation:SmallAngleBetweenTangentSapces},
\begin{align*}
\angle  (q_1- q_2, \Tan(p, \M) ) &\leq \angle  (\Tan(p, \M), \Tan(q_1, \M) ) +  \angle  (q_1- q_2, \Tan(q_1, \M) ) \\
&<  \frac{\pi}{4} + \frac{\pi}{6} < \frac{\pi}{2}, 
\end{align*}
which cannot be since $q_2 - q_1$ is orthogonal to $ \Tan(p, \M)$. Hence, the claim is proved.

Since the restriction to $\M \cap B(p, \epsilon)$ of the orthogonal projection on $p+\Tan(p, \M)$ is an  injective continuous  map, from an
open $n$-manifold to the $n$-manifold  $p+\Tan(p, \M)$, invariance of domain implies that it is an homeomorphism on its image.
This means that $\M \cap B(p, \epsilon)$ is the graph of a map $x \mapsto \phi(x)$ from some open set $U_p \subset \Tan(p, \M)$ to $\Nor(p,\M)$, i.e. $x \mapsto p + x + \phi(x)$ is a local homeomorphism from $U_p$ to $\M$. Moreover, these maps induce an atlas for $\M$. 

Definition \ref{def:4.3and4.4Fed} and the fact that $\Tan(p,\M)$ is a $n$-dimensional linear space together imply that $\phi$ is differentiable at $0$ with $D\Phi (0) = 0$, 
 and more generally that $\phi$ is differentiable at any $x \in U_p$. The continuity \eqref{equation:SemiContinuityTangent} of $q \mapsto \Tan(q, \M)$ for the Grassmannians metric yields that $\phi$ is of class $C^1$.
\end{proof}




