\begin{equation}\label{eq:DistToTgtGreater_2}
 d_{\mathbb{E} } (q' ,\: q \: + \Tan(q, \M ) >  \frac{|q-q'|^2}{2r}.
 \end{equation}
Looking at Figure \ref{fig:GraphOfSemiConvex}, we see that \eqref{eq:DistToTgtGreater_2} translates into
\[
|q'-q_1|  >  \frac{|q-q'|^2}{2r},
\]
 which is equivalent to 
\[ \frac{|q-q'|^2}{2r |q'-q_1|} < 1 .\]
Because the left hand side is strictly less than $1$, there exists a $\theta'>0$ such that $\cos \theta' >  \frac{|q-q'|^2}{2r |q'-q_1|}$. 
This means that in the context of Lemma \ref{lemma:SmallLemma},
one can choose $\eta$ (where we take $\alpha =\eta$ in Lemma \ref{lemma:SmallLemma}) % $\eta$ plays the role of $\alpha$ %, and in this lemma $\eta$ yields a maximal angle $\theta$
small enough to get $\cos \theta >  \frac{|q-q'|^2}{2r |q'-q_1|}$. 
Because the angle between $\Tan(p,\M)$ and $\Tan(q,\M)$ is upper bounded by $\theta$ examining the triangle $q'q_1q_2$ in Figure \ref{fig:GraphOfSemiConvex} yields that $|q'-q_2| \geq |q'-q_1| \cos \theta$, which combined with the previous result yields 
\[
|q'-q_2|  >  \frac{|q-q'|^2}{2r}. 
\]
Writing 
\[
v = \frac{q'-q_2}{|q'-q_2|} \in \Nor(p,\M),
\]
so that $|q'-q_2| = \langle v, q'-q_2\rangle$ and  using 
 $|q-q'| > |y'-y|$, this can be reformulated into 
\begin{align}\label{eq:far_first_order}
 \langle v, q'-q_2\rangle  \geq  \frac{|y'-y|^2}{2r}.
\end{align}

Because
\[
 q' - q_2 = \Big( 0, \: \phi(y') - \big(\phi(y) + D\phi(y) (y'-y) \big) \Big)_{\Tan_p\M \times \Nor_p\M},
 \]
and $f(y) \defunder{=} \langle v, \phi(y) \rangle$,
 we may rewrite \eqref{eq:far_first_order} as
\begin{align}\label{eq:below_first_order}
 \frac{|y' - y |^2}{2r} + f(y') <  f(y) + Df(y) (y'-y) . 
\end{align}

The function  $x \mapsto  g(x) = \frac{|x - y |^2}{2r} + f(x)$
is not convex since \eqref{eq:below_first_order}
says that $g(y')$ is below the first order Taylor expansion of $g$ at $y$.
\end{proof}



