\begin{proof}[Proof of Lemma \ref{lemma:FromOperatorNormToAngles}]
The angle between $L_1$ and $L_2$ is a attained in a pair of vectors, that is there exists $v_1 \in L_1$ and $v_2 \in L_2$ such that
\[
 \angle L_1, L_2 = \angle v_1, v_2 = \min_{v'_2 \in L_2} \angle v_1, v'_2 = \max_{v'_1 \in L_1}  \min_{v'_2 \in L_2} \angle v'_1, v'_2 =\max_{v'_2 \in L_2}  \min_{v'_1 \in L_1} \angle v'_1, v'_2, 
\]
where the last equality follows from Lemma \ref{lemma:anglebetweenKVectorSpacesIsSymmetric}.  This explains the asymmetrical expression. 

For some $v_0 \in \R^n$, with $|v_0| = 1$, and $\lambda >0$, 
we have  $v_1=  \lambda (v_0, F_1(v_0))$ and therefore
\begin{equation}\label{equation:angleLinearSpacesUpperBoundedByAngleImageSameVector}
 \angle L_1, L_2 = \angle (v_0, F_1(v_0)) , v_2 \leq \angle  (v_0, F_1(v_0)) ,  (v_0, F_2(v_0)),
\end{equation}
because, by definition of $F_2$, we have $(v_0, F_2(v_0)) \in L_2$.

Since $| (v_0, F_1(v_0)) |, | (v_0, F_2(v_0)) |  \geq 1$, one has:
\begin{align*}
2 \sin  \frac{  \angle  (v_0, F_1(v_0)) ,  (v_0, F_2(v_0))     }{2} 
&\leq \big|  (v_0, F_2(v_0)) - (v_0, F_1(v_0)) \big| \\
& = \big|    F_2(v_0) - F_1(v_0) \big|  \leq \big\| F_2 - F_1 \big\|.
\end{align*}
This with \eqref{equation:angleLinearSpacesUpperBoundedByAngleImageSameVector}
gives the inequality of the lemma.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lemma:MIsC11WithOptimalBounds}]
{
If $\M$ has local reach $\rch_{loc.}({\M}) =\infty$, \eqref{eq:MetricDefREach} implies that all geodesics are straight lines, that is every connected component of $\M$ is convex. 
Therefore, because $\M$ does not contain a boundary by assumption, every connected component of $\M$ is affine and the statement holds. This means that we can concentrate on the case where $\rch_{loc.}({\M})<\infty$. 
}

Lemma \ref{lemma:phiIsC11} already says that  $\M$ is $C^{1,1}$ embedded by considering the atlas defined by projections on local tangent spaces.
Now, (if $p_1$ and $p_2$ lies in the same connected component of $\M$) considers (thanks to Lemma \ref{Menger}) a geodesic $\gamma$ of length $L= d_{\M} (p_1, p_2)$
joining $p_1$ and $p_2$. Take $\epsilon >0$ and $\theta >0$.  By application of Lemma \ref{lemma:phiIsC11} there is at each point $q\in \gamma([0,L]) $ an open neighborhood $V_q$ of 
$q$ in $\M$, such that $V_q$ is the graph of a map $\phi_q$ from $\Tan(q, \M)$ to $\Nor(q, \M)$ whose derivative is bounded by
 $\tan \theta$ and, if $R\leq \rch_{loc.}(\M)$, is $\frac{1}{(R - \epsilon)}$-Lipschitz (in the sense of Lemma 
\ref{lemma:phiIsC11}). Consider for each $t \in [0,L]$ an open interval $(t^-, t+)$ such that $\gamma((t^-, t+) \cap [0, L] ) \subset V_{\gamma(t)}$. 
By compactness, one can extract a finite open cover of $[0,L]$ by intervals in the form $(t_i^-, t_i^+)_{i=0, N}$, with $t_i \in (t_i^-, t_i^+)$, $t_0 = 0$ and $t_N = L$.
One can therefore find a finite sequence $0=t'_0< \ldots <t'_{N'} = L$ such that for any $j$ such that $0 \leq j < N'$, there is 
some $i$ such that $[t'_j, t'_{j+1}] \subset (t_i^-, t_i^+)$.
Since $\gamma(t'_0) = \gamma(0) = p_1$ and $\gamma(t'_{N'}) = \gamma(L) = p_2$, one has:
\begin{equation}\label{equation:angleBoundedByDeviationAlongGeodesic}
\angle \Tan(p_1, \M) , \Tan(p_2,\M) \leq   \sum_{j=0}^{N'-1} \angle \Tan(\gamma (t'_{j}) , \M) , \Tan( \gamma (t'_{j+1}),\M)
\end{equation}
The segment of geodesic $\gamma([t'_j, t'_{j+1}]$ belongs to the graph of the map from $\Tan(\gamma(t_i), \M)$  which
derivative is $\frac{1}{(R - \epsilon)}$-Lipschitz for the operator norm, we get 
from Lemma \ref{lemma:FromOperatorNormToAngles}   that: 
\[
2 \sin \frac{\angle \Tan(\gamma (t'_{j}) , \M) , \Tan( \gamma (t'_{j+1}),\M)  }{2}
\leq  \frac{1}{(R - \epsilon)}   \left| \pi_{\Tan(\gamma(t_i), \M)} (\gamma (t'_{j+1})) - \pi_{\Tan(\gamma(t_i), \M)} (\gamma (t'_{j})) \right| 
\]
and, since:
\[
\left| \pi_{\Tan(\gamma(t_i), \M)} (\gamma (t'_{j+1})) - \pi_{\Tan(\gamma(t_i), \M)} (\gamma (t'_{j})) \right| \leq \left| \gamma (t'_{j+1}) - \gamma (t'_{j}) \right| 
\]
we get:
\[
2 \sin \frac{\angle \Tan(\gamma (t'_{j}) , \M) , \Tan( \gamma (t'_{j+1}),\M)  }{2}
\leq  \frac{1}{(R - \epsilon)} \left| \gamma (t'_{j+1}) - \gamma (t'_{j}) \right| 
\]
Since $\angle \Tan(\gamma (t'_{j}) , \M) , \Tan( \gamma (t'_{j+1}),\M) < 2 \theta$ and $\theta \mapsto \frac{\sin \theta}{\theta} $ is decreasing for positive small $\theta$,  one has:
\[
 2 \sin \frac{\angle \Tan(\gamma (t'_{j}) , \M) , \Tan( \gamma (t'_{j+1}),\M)  }{2} > \frac{\sin \theta}{\theta}  \angle \Tan(\gamma (t'_{j}) , \M) , \Tan( \gamma (t'_{j+1}),\M) 
 \]
 so that \eqref{equation:angleBoundedByDeviationAlongGeodesic} gives:
\[
\angle \Tan(p_1, \M) , \Tan(p_2,\M) \leq   \sum_{j=0}^{N'-1}  \frac{\theta}{(R - \epsilon) \sin \theta}  \left| \gamma (t'_{j+1}) - \gamma (t'_{j}) \right|  \leq   \frac{\theta}{(R - \epsilon) \sin \theta}  d_{\M} (p_1, p_2)
\]
Since the last inequality holds for any $\theta >0$ and $\epsilon >0$, the lemma is proved.
\end{proof}


