\begin{proof}[Proof of Theorem \ref{PosReachImpliesOptimalSizeNeighbourAsGraph}] 
Thanks to Theorem \ref{theorem:ReachEquivalentMetricDistorsion} we have that for $q \in \M \cap B^\circ(p, \sqrt{2}\: \rch(\M))$
\[ 
d_{\M}(q,p) \leq 2\,  \rch(\M)  \arcsin \frac{|q-p|}{ 2 \rch(\M)} <  2\,  \rch(\M)  \arcsin \frac{\sqrt{2}\: \rch(\M)}{ 2 \rch(\M)} = \frac{\pi}{2} \rch(\M) . 
\] 
Now using Theorem \ref{ReachImpliesQuantifiedLipschitzDerivative} or Lemma \ref{lemma:MIsC11WithOptimalBounds}, this implies that 
 \[
 \angle \Tan(p, \M), \Tan(q,\M) \leq  \frac{1}{ \rch(\M) }  d_{\M} (p, q)<  \frac{\pi}{2} . 
\]
The submersion theorem now yields that the orthogonal projection $\pi _{T_p \M}$ from $\M \cap B^\circ(p, \sqrt{2}\: \rch(\M))$ onto $\Tan(p,\M)= T_p\M$ is a local diffeomorphism.  

We recall that the covering number of a point in the image of a map is the number of points in the preimage above that point. 
Because the orthogonal projection $\pi _{T_p \M}$ is a local diffeomorphism, the covering number is constant on $ B^\circ(0,\rch(\M)) \subset T_p\M$ except when one crosses the boundary $\partial \big( \overline{ \M \cap B^\circ(p, \sqrt{2}\: \rch(\M))}  \big)$. However, we claim that 
\[ 
\partial \big( \overline{ \M \cap B^\circ(p, \sqrt{2}\: \rch(\M))}  \big) \cap \pi_{T_p\M}^{-1} (B^\circ(0,\rch(\M))) = \emptyset. 
\]
This claim can be established as follows: To derive a contradiction we assume that $q\in \partial \big( \overline{ \M \cap B^\circ(p, \sqrt{2}\: \rch(\M))}  \big)$, and write $q=x+n$, with $x \in B^\circ(0,\rch(\M)) \subset T_p\M$ and $n \in N_p\M$. Then by Pythagoras we have that $n> \rch(\M)$.  This contradicts the characterization of the reach given in Lemma \ref{Lem:distanceToTangentCharacter}. 
% Theorem \ref{Fed4.18}.

We therefore conclude that the covering number is constant on $B^\circ(0,\rch(\M)) \subset T_p\M$. However, thanks to Lemma \ref{lemma:embeddedManifoldPositiveReachThenC1Embedded} the covering number is one at $0$ and in fact in a neighbourhood of zero. Hence the covering number is $1$ on $B^\circ(0,\rch(\M)) \subset T_p\M$. Because $\M$ and the graph is locally $C^{1,1}$ it is globally $C^{1,1}$ and the result follows. 
%
%It remains to verify that $B^\circ(0,\rch(\M)) \subset T_p\M$, where we identify $0$ with $p$ lies completely in the image. The statement is true is a neighbourhood $U_p$ of $p$ thanks to Lemma \ref{lemma:embeddedManifoldPositiveReachThenC1Embedded}. So, to derive a contradiction, assume that $x$ is the point in $T_p\M$ that is the closest to $0$ that is no longer in the image of the projection. This means that $\M$ has to leave $B^\circ(p, \sqrt{2}\: \rch(\M))$ at $x + n$, with $n \in N_p\M$. By Pythagoras this means that $n> \rch(\M)$, but this contradicts the characterization of the reach given in Theorem \ref{Fed4.18}. 
\end{proof} 

\begin{proof}[Proof of Lemma \ref{cor:OtherPaper}] 
In the proof of Lemma \ref{lemma:VDotphiIsSemiConvex} we pick $\theta\in [ 0 ,\pi /2]$ such that 
\begin{align} 
 \cos^3 \theta > \frac{R- \epsilon}{R}. 
\tag{\ref{eq:boundTheta}}
\end{align} 
Given $\theta$ we then choose an $\alpha>0$ so that
\begin{align} 
| y  | \leq \alpha \Rightarrow  \angle \Tan(p, \M), \Tan(q, \M) < \theta.
\tag{\ref{eq:BoundYTheta}}
\end{align} 
Because $\frac{d^3}{d\theta^3 } \cos^3 (\theta)= \sin (\theta) ( 21 \cos^2 (\theta) -6 \sin^2 (\theta) ) \geq 0$ if $\theta \in [0,\pi /4]$ , Taylor's Theorem with integral remainder yields that remainder the $R(\theta)$ in
\[ 
\cos^3 (\theta) = 1- \frac{3}{2} \theta^2  + R(\theta)
\] 
is positive, if $\theta \in [0,\pi /4]$. As $\cos^3(\theta)$ is monotone on $[0,\pi/2]$ and 
\[
\cos \left( \frac{\pi}{4} \right  ) = \frac{1}{2 \sqrt{2}} < 1/2 \leq  \frac{R- \epsilon}{R},
\] 
and hence $\theta \in [0,\pi /4]$, 
Therefore it follows that 
\[ 
\cos^3 (\theta) \leq 1- \frac{3}{2} \theta^2 \leq 1-\theta^2,
\]
%As can be verified using a computer algebra system (such as Mathematica) 
%we have that 
%\begin{align}
%1-\theta^2 \geq \cos ^3 \theta
%\nonumber
%\end{align} 
which in combination with \eqref{eq:boundTheta} gives that $\theta^2 \leq \frac{\epsilon}{R}$. 
We need to bound $\alpha$ such that $\angle \Tan(p, \M), \Tan(q, \M) < \theta$, but thanks to Lemma \ref{lemma:MIsC11WithOptimalBounds} we know that 
 \[
 \angle \Tan(p, \M), \Tan(q,\M) \leq  \frac{1}{R }  d_{\M} (p,q),
