\rch_{loc.}(p, \Su) &\geq \inf_{q\in \Su \cap B^{\circ}(p, \rho)} \:  \rch_{loc.}(q, \Su) \\
&= \inf_{q\in \Su \cap B^{\circ}(p, \rho)} \:  \rch_{loc.}(q, \Su \cap B(p, \rho) ) \\
%&  \geq  \rch_{loc.}( \Su \cap B(p, \rho) ) \quad \text{by \eqref{eq:DefLocReach2} applied to the set}  \: \Su \cap B(p, \rho),  \\
%& \geq  \rch( \Su \cap B(p, \rho) ) \quad \text{by \eqref{leq:LocalReachLargerThanReach}}, \\
%&> \rch_{loc.}(p, \Su) - \epsilon \quad  \text{by \eqref{leq:ReachInLocalBallIConvergesToLocalReach}.}
&  \geq  \rch_{loc.}( \Su \cap B(p, \rho) ) \tag{by \eqref{eq:DefLocReach2} applied to the set $\Su \cap B(p, \rho)$}  \\
& \geq  \rch( \Su \cap B(p, \rho) ) \tag{by \eqref{leq:LocalReachLargerThanReach}} \\
&> \rch_{loc.}(p, \Su) - \epsilon .  \tag{by \eqref{leq:ReachInLocalBallIConvergesToLocalReach}}
\end{align*}
Because this inequality holds for any positive $\epsilon$, the equality follows. 
\end{proof}

\begin{proof}[Proof of Lemma \ref{lemma:LocalReachMakeGeodesicsStraight}] 
The length of $\gamma$ in the direction $\dot{\gamma}(\frac{\ell}{2})$ is
\begin{align}
\left \langle q-p , \dot{\gamma} \left( \frac{\ell}{2} \right) \right \rangle &= \int_{0}^{\ell} \langle \dot{\gamma}(s), \dot{\gamma}(\ell/2) \rangle \ud s 
\nonumber
\\
&= \int_{0}^{\ell/2} \langle \dot{\gamma}(s), \dot{\gamma}(\ell/2) \rangle \ud s +\int_{\ell/2}^{\ell} \langle \dot{\gamma}(s), \dot{\gamma}(\ell/2) \rangle \ud s
\nonumber 
\\
&\geq \int_{0}^{\ell/2} \cos \frac{|s-\ell/2| } {R}  \ud s +\int_{\ell/2}^{\ell} \cos \frac{|s-\ell/2| } {R}  \ud s 
\nonumber
\\
&= 2 \, R\sin \left(\frac{ \ell }{2 R} \right).
\nonumber
\end{align}
{where, in the above inequality, we use the assumption
$\ell \leq 2 \pi R$ and the fact that  $\theta \mapsto  \cos \theta$ 
is decreasing on $[0,\pi]$.} 


Because $|q-p| \geq \langle q-p , \dot{\gamma}(\frac{\ell}{2}) \rangle$, we see that 
\[ 
|q-p| \geq 2 \, R \sin \left(\frac{ \ell }{2R} \right).
\] 
\end{proof} 


\begin{proof}[Proof of Lemma \ref{lemma:SemiContinuitySpecialCase}]
Consider the closed set $\Su' := \Su \setminus B^{\circ}(  \tilde{x} , \epsilon )$.
The minimum distance $d(x, \Su')$ to $x$ is attained at least at some point $z$ in $\Su'$
so that
\[
d(x, \Su') = d(x, z) > d(x, \tilde{x} ) = d(x, \Su).
\]
Taking
\[ \alpha := \frac{ d(x, \Su') - d(x, \Su)}{2},
\]
we get, for any $y$ such that $|y-x|< \alpha$ and $z \in \Su'$ that:
\begin{align*}
d(y, z)  &\geq d(y, \Su') \geq d(x, \Su')  - d(y,x) \\
& =  d(x, \Su) + 2 \alpha   - d(y,x)  =   d(x, \tilde{x} )  + 2 \alpha   - d(y,x) \\
&>  d(x, \tilde{x} ) + d(y,x) \geq  d(y, \tilde{x} ) \geq d(y, \Su).
\end{align*}
We have shown that if $z \in \Su'$, then $d(y, z) > d(y, \Su)$. It follows that 
any closest point to $y$ in $\Su$ is in $\Su \setminus \Su' = \Su \cap B^{\circ}(  \tilde{x} , \epsilon )$
which is \eqref{eq:SemiContinuitySpecialCase}.
\end{proof}


