\subsection{Terrain Analysis} \label{sec:4.5}
To improve the accuracy of extrinsic parameter estimation between the base LiDAR and the virtual LiDAR, it is crucial to account for the variability in terrain. In environments where the ground is not uniformly flat, the precision of the parameter estimation may be inaccurate. To minimize the impact of uneven ground on the estimation process, we have implemented a terrain analysis method. This method involves selecting the flattest ground segment on which the extrinsic parameter estimation is performed. The process of this method are illustrated in Fig \ref{terrain_analysis}.

To begin with, the point cloud map is built based on the base LiDAR poses estimated in Sec. \ref{sec:4.4}. Next, the patchwork++ mthod is used to extract the ground \cite{Lee2022}. Afterward, the local ground is cropped for each base LiDAR pose. The roughness of each local ground is then computed using Eq. \eqref{eq4-F-1}. 
\begin{equation} \label{eq4-F-1}
    \begin{aligned}
        r = \sqrt{\frac{1}{N} \sum\limits^{N}_{i=1}\left(d_i - \overline{d} \right)}
    \end{aligned}
\end{equation}
where $r$ represents the roughness; $d_i$ denotes the distance of the $i$-th point to the fitted ground plane model, and $\overline{d}$ denotes the average distance.

Finally, the local ground with the lowest roughness is used to estimate the extrinsic parameter between the base LiDAR and virtual LiDAR using Eq. \eqref{eq4-F-2} and Eq. \eqref{eq4-F-3}.

\begin{equation} \label{eq4-F-2}
    \begin{cases}
        \mathbf{u} = \frac{\mathbf{n}_1 \times \mathbf{n}_2}{\left\| \mathbf{n}_1 \times \mathbf{n}_2 \right\|}\\
        \theta = \arccos{(\mathbf{n}_1\cdot\mathbf{n}_2)}\\
        \mathbf{R} = \mathbf{I}+[\mathbf{u}]_{\times}\sin{\theta}+[\mathbf{u}]_{\times}^2(1-\cos{\theta})\\
        \mathbf{t} = [0, 0, d_1-d_2]^{\mathrm{T}}\\
    \end{cases}
\end{equation}
\begin{equation} \label{eq4-F-3}
        {_{L_0}^{V_L}\mathbf{T}} = 
        \left [\begin{matrix}
    \mathbf{R} & \mathbf{t} \\
    0 & 1 
    \end{matrix} \right ]
\end{equation}
where $[\mathbf{n}_1^{\mathrm{T}},d_1]$ define the parameterized representations of the local ground, $[\mathbf{n}_2^{\mathrm{T}},d_2] = [0, 0, 1, 0]^{\mathrm{T}}$ define the ground plane in the virtual LiDAR coordinate system, $\mathbf{u}$ stands for a unit vector orthogonal to both $\mathbf{n}_1$ and $\mathbf{n}_2$, $\theta$ denotes the angle between $\mathbf{n}_1$ and $\mathbf{n}_2$, $\mathbf{R}$ is derived through Rodrigues' rotation formula, and $\mathbf{t}$ represents the translation component.

\subsection{Joint Optimization}
In the joint optimization step, LiDAR data and GINS data are tightly coupled to estimate refined extrinsic parameters. This process considers three types of factors.
\begin{enumerate}
    \item GINS Installation Height Factor: This factor imposes a constraint on the unobservable direction of the VLiDAR-GINS extrinsic parameter, accounting for the plane motion of vehicles. It is mathematically expressed as Eq. \eqref{eq4-G-1}.
    \item General Matching Factors 1 and 2: These involve multi-LiDAR and VLiDAR-GINS extrinsic parameters, respectively. They minimize the difference between points, as described by Eq. \eqref{eq4-G-2} and Eq. \eqref{eq4-G-3}. It should be noted that the GINS poses are also treated as optimized variables, though they are considered as measurements in Eq. \eqref{eq4-C-1}. The reason for this is illustrated in Sec. \ref{sec:4.3}.
    \item Motion Constraint Factor: This factor encompasses the base LiDAR poses, GINS poses, and VLiDAR-GINS extrinsic parameters, detailed in Eq. \eqref{eq4-G-4}.
\end{enumerate}

\begin{equation} \label{eq4-G-1}
  \begin{aligned}
    {^{1}\mathbf{r}} = \mathrm{Log} \left(\mathbf{y} \,  {^{V_L}_G}\mathbf{T}{^{-1}}\right)
  \end{aligned}  
\end{equation}
\begin{equation} \label{eq4-G-2}
    \begin{aligned}
        {^{2}\mathbf{r}^{kl}_{t_i t_j}} &= {^{W}_{G}\mathbf{T}_{t_i}} {^{G}_{V_L}\mathbf{T}} {^{V_L}_{L_{0}}\mathbf{T}} {\left(^{L_0}\mathbf{p}^k\right)_{t_i}} - {^{W}_{G}\mathbf{T}_{t_j}} {^{G}_{V_L}\mathbf{T}} {^{V_L}_{L_{0}}\mathbf{T}} {\left(^{L_0}\mathbf{p}^k\right)_{t_j}}
    \end{aligned}
\end{equation}
\begin{equation} \label{eq4-G-3}
    \begin{aligned}
        {^{3}\mathbf{r}^{kl}_{t_i t_j}} &= {^{W}_{L_0}\mathbf{T}_{t_i}} {^{L_0}_{L_m}\mathbf{T}}{\left(^{L_m}\mathbf{p}^k\right)_{t_i}} - {^{W}_{L_0}\mathbf{T}_{t_j}} {^{L_0}_{L_n}\mathbf{T}} {\left(^{L_n}\mathbf{p}^l\right)_{t_j}}
    \end{aligned}
\end{equation}
\begin{equation} \label{eq4-G-4}
    \begin{aligned}
         {^{4}\mathbf{r}_{t_i t_j}} = \mathrm{Log} \left({^{V_L}_{G}}\mathbf{T} \,
        {^{W}_{G}}\mathbf{T}_{t_j}^{-1} \, {^{W}_{G}}\mathbf{T}_{t_i} \,  {^{V_L}_{G}}\mathbf{T}^{-1} \,   {^{W}_{L_0}\mathbf{T}_{t_i}^{-1}} \, {^{W}_{L_0}\mathbf{T}_{t_j}} \right)
    \end{aligned}
\end{equation}
These three types of factors are integrated into a unified cost function, shown in Eq. \eqref{eq4-G-5}, which is then optimized using the Levenberg-Marquardt (LM) optimizer.
\begin{equation} \label{eq4-G-5}
    \begin{aligned}
         f(\hat{\mathcal{X}}) = &\left\| {^{1}\mathbf{r}} \right\|^2_{^{1}\Sigma} + \sum\limits_{t_i,t_j} \sum\limits_{k,l} \left\| {^{2}\mathbf{r}^{kl}_{t_i t_j}} \right\|^2_{^{2}\Sigma} + \\ &\sum\limits_{t_i,t_j} \sum\limits_{k,l} \left\| {^{3}\mathbf{r}^{kl}_{t_i t_j}} \right\|^2_{^{3}\Sigma} + \sum\limits_{t_i,t_j} \left\| {^{4}\mathbf{r}_{t_i t_j}} \right\|^2_{^{4}\Sigma}
    \end{aligned}
\end{equation}
where ${^{1}\Sigma}$, ${^{2}\Sigma}$, ${^{3}\Sigma}$ and ${^{4}\Sigma}$ represent the corresponding covariance matrices of ${^{1}\mathbf{r}}$, ${^{2}\mathbf{r}^{kl}_{t_i t_j}}$, ${^{3}\mathbf{r}^{kl}_{t_i t_j}}$ and ${^{4}\mathbf{r}_{t_i t_j}}$, respectively.

The optimization process yields the VLiDAR-GINS and multi-LiDAR extrinsic parameters. Then, the extrinsic parameters between the base LiDAR and the GINS system can be calculated using Eq. \eqref{eq4-G-6}.
\begin{equation} \label{eq4-G-6}
    \begin{aligned}
         {^{L_0}_{G}}\mathbf{T} = {^{L_0}_{V_L}\mathbf{T}} \, {^{V_L}_{G}}\mathbf{T}
    \end{aligned}
\end{equation}

