\section{DBMs, SDBMs, and HSDBMs}

We consider sets over the integers only, i.e., subsets of $\Zbb^n$ for some $n \in \Nbb$. We first define some notation.
For $m, n \in \Nbb$, $[n]$ denotes the set $\{1, \dots n\}$, $n\Zbb$ denotes the set of integer multiples of $n$, and $m \mid n$ denotes that $m$ divides $n$. 
If $G$ is a weighted graph with no negative cycles and $u$ and $v$ are vertices in it, then $\delta_G(u, v)$ is the distance from $u$ to $v$ in $G$. $\lfloor x \rfloor_y$ refers to $x$ rounded down to the nearest multiple of $y$ smaller than or equal to $x$. If $x, y$ are vectors and $t$ a scalar, $x + t$ refers to element-wise addition.

Let us first formally recall the definition of Difference Bound Matrices (DBM) over integers and their properties~\cite{dill1990dbm,mine2001dbm} before presenting SDBM.

% \subsection{Difference Bound Matrices}
\label{sec:dbm}

\begin{definition}
\label{def:dbm}
A \emph{Difference Bound Matrix (DBM)} is a constraint system over variables $x_1, \dots x_n \in \Zbb$ of the form
\begin{align*}
- x_i + x_j \le c_{ij}
&& \ell_i \le x_i \le u_i
&& (i, j, c_{ij}) \in E \textrm{ and } l_i, l_j \in \Zbb
\end{align*}
where $E \subseteq [n] \times [n] \times \Zbb$ denotes the set of difference bound constraints. We will use $m = |E|$ to denote the number of such constraints.

Not all upper and lower variable bounds $\ell_i$, $u_i$ may be present. When no such variable bounds are present we call the system \emph{variable-bound-free (VBF)}; otherwise we say that the system has variable bounds.
\end{definition}
%
It is known that the satisfiability of DBM constraints can be determined in $\Ocal(n^3)$ time and $\Ocal(n^2)$ space \cite{DBLP:conf/ifip/BerthomieuM83,DBLP:journals/corr/abs-cs-0703084}. We now define two special cases of Presburger sets derived from DBMs by introducing additional congruence constraints.


% \begin{definition}[DBM with Variable Bounds]
% \label{def:dbm-with-bounds}
% A DBM with additional upper and lower bound constraints
% \begin{align*}
% \ell_i \le x_i \le u_i,
% \end{align*}
% not all of which need exist.
% \end{definition}

% We analogously define SDBMs with variable bounds and HSDBMs with variable bounds. To be explicit, the versions without bounds will be called variable-bound-free DBMs, SDBMs, and HSDBMs.

\begin{lemma}[DBM Shifting Lemma]
\label{lem:dbm-shift}
If $x$ is a solution to a VBF DBM, then so is $x + t$ for $t \in \Zbb$, i.e., adding a constant to all variables preserves satisfiability.
\end{lemma}
\begin{proof}
All constraints are bounds on differences of variables, and the differences don't change when adding a constant to all variables.
\end{proof}
\begin{corollary}
If $S_{i,t}$ is the set of solutions to a VBF DBM such that $x_i = t$, then $S_{i,t} = \{x + t \mid x \in S_{i,0}\}$.
\end{corollary}

Given a DBM with variable bounds, we can construct a new VBF system by adding a new variable $x_0$ and converting all variable bounds $\ell_i \le x_i \le u_i$ to difference bound constraints $\ell_i \le x_i - x_0 \le u_i$.
Clearly $(x_1, \dots x_n)$ is a solution to the original system iff $(0, x_1, \dots x_n)$ is a solution to the new system. By the above lemma, the new system has a solution with $x_0 = 0$ iff it has any solution. Thus the original DBM with variable bounds is satisfiable iff the new VBF DBM is. VBF DBMs are best understood by analyzing their \emph{potential graphs}.

\begin{definition}
The \emph{potential graph of a DBM} is a weighted directed graph over vertex set $[n]$ with an edge from $i$ to $j$ of weight $c_{ij}$ for each $(i, j, c_{ij}) \in E$. The weights may be negative and the graph may contain negative cycles.
\end{definition}

% \begin{lemma}
% \label{lem:dbm-unsat}

% \end{lemma}
% \begin{proof}
% Let's say that $$
% \end{proof}

\begin{lemma}
\label{lem:dbm-path}
Let $G = ([n], E)$ be the potential graph of a DBM. If $G$ has a path from vertex $u$ to $v$ of total weight $W$,
then $-x_u + x_v \le W$ for every solution $x$ to the DBM.
\end{lemma}
%
\begin{corollary}
\label{lem:dbm-dist-bound}
If the graph has negative cycles, then no solution $x$ exists.

If the graph has no negative cycles, then for all $u, v \in [n]$, it holds that $-x_u + x_v \le \delta_G(u, v)$.
This is useful to define a normal form of the DBM.
\end{corollary}

\begin{definition}
A \emph{path-closed DBM} is one that is satisfiable and, for all $u, v$ such that there exists a path from $u$ to $v$ in the potential graph $G$, the bound on $-x_u + x_v$ exists and is equal to $\delta_G(u, v)$.
\end{definition}

Clearly, any DBM can be brought to path-closed form by computing the distances in the potential graph, and by \autoref{lem:dbm-dist-bound}, doing so does not change the solution set. Moreover, the path-closed form has the following useful property.

\begin{lemma}[DBM Projection Lemma]
\label{lem:dbm-proj}
If a DBM is path-closed, then the projection of its solution set onto a subset of variables is equal to the
solution set of the constraints involving only those variables.
\end{lemma}

It follows that the path-closed form is the tightest constraint system with the same solution set as the original system, i.e., in a path-closed DBM there exist solutions on the surface of every inequality, so no inequality can be further tightened without changing the solution set. Moreover, if there is no constraint on some $-x_i + x_j$ then adding any upper bound on this changes the solution set. 
% Of course, the above holds for extending an assignment to any subset of variables, but we only use the above form.
Finally, the following is useful to compute a complete explicit solution.

\begin{lemma}
\label{lem:dbm-vert-dist-soln}
For any vertex $u$ in the potential graph from which all other vertices are reachable, the assignment $x_v = \delta_G(u, v)$ satisfies the DBM.
\end{lemma}
Note that in this solution, $x_u = 0$.
