% \begin{definition}
% A graph $G$ is called \emph{transitively closed} if it % contains no negative cycles and if, whenever there is a path from $u$ to $v$, there is an edge from $u$ to $v$ of weight $\delta_G(u, v)$.
% \end{definition}

\begin{lemma}
\label{lem:induced-fw}
Let $G = (V, E)$ be a transitively closed graph with no negative cycles, i.e.\ whenever there is a path from $u$ to $v$, there is an edge from $u$ to $v$ of weight $\delta_G(u, v)$. Let $U \subseteq V$. Now let $F$ be a copy of $E$ in which we have decreased the weights of some edges that go from one vertex in $U$ to another in $U$. Finally, let $H = (V, F)$.

Suppose that $H$ has no negative cycles. Then for any vertices $u$ and $v$ in $U$ with a path from $u$ to $v$, there is a shortest path from $u$ to $v$ that never leaves $U$.
\end{lemma}
\begin{proof}
Let $p = (p_1, \dots p_k)$ be the vertices of a path starting and ending in $U$ and with all the intermediate vertices lying outside $U$. Let $W$ be the weight of $p$ in $H$ and let $c$ be the weight of the edge from $p_1$ to $p_k$ in $H$. Then $W \ge \delta_G(p_1, p_k)$ because only edges that stay within $U$ decreased, and $\delta_G(p_1, p_k) \ge c$ because the edge in $G$ had weight equal to $\delta_G(p_1, p_k)$ and it can only have decreased or stayed the same in $H$. Thus the path $p$ cannot have weight less than the weight of the direct edge in $H$.

For a general path that goes in and out of $U$ repeatedly, we can always replace all sections of the path that go outside and come back in with the direct edges that stay in $U$, to obtain a path within $U$ whose weight is at most that of the original path. Thus for any start and end point in $U$, the shortest path that stays in $U$ has weight equal to the shortest path in the entire graph $H$.
\end{proof}

\begin{theorem}
\label{thm:hsdbm-runtime}
\textsc{SolveHSDBM} in \autoref{fig:sat} terminates in $O(n^4)$ time.
\end{theorem}

\begin{proof}
We will view the algorithm as operating on the potential graph; all modifications to $c_{ij}$ then become modifications to the edge weights. We will show that at most $n - 1$ repetitions are needed for fixpoint. We prove that after the $i$th application of GCD tightening, all edges between vertices in $\{v_i, \dots v_n\}$ will stay multiples of $d_i$ for the rest of the algorithm. We prove this by induction. The base case for $i = 1$ is true since when all edges are multiples of $d_1$, path-closure cannot change this divisibility, and GCD-tightening will not change this either.

Now assume it to be true for $i$; we will show it for $i + 1$. The $i + 1$-th application of GCD tightening only decreases edge weights between vertices in $U = \{v_{i+1}, \dots v_n\}$, by the induction hypothesis. Now we want to analyze how path closure affects the edge weights in the subgraph induced by $U$.
% By \autoref{lem:induced-fw}, 
% the distances between vertices in $U$ are equal to their distance in the subgraph induced by $U$, so as far as such edges are considered we can consider that the next path-closure step is performed only in the induced subgraph on $U$.
After tightening, all edges in the subgraph are multiples of $d_{i+1}$, so distances between nodes in the subgraph are also multiples of $d_{i+1}$ by 
\autoref{lem:induced-fw}.
Thus path closure does not affect divisibility at this step. Therefore, subsequent GCD-tightening does not affect it either. Repeated applications of these preserve the property.

Thus the $n$th application of GCD tightening does nothing since there are no edges in the graph induced on the single vertex $v_n$ for $i = n$. Therefore, neither does the subsequent application of path-closure. Thus, fixpoint is achieved after $n - 1$ runs of GCD-tightening and path-closure.
\end{proof}

