\section{Deferred Proofs}
\label{app:lemmas}

\begin{theorem}
\label{thm:sdbm-sat-np-hard}
The satisfiability problem for simple SDBMs is \NP-hard.
\end{theorem}
\begin{proof}
Let $x$ be a solution to the simple SDBM
\begin{align*}
x_1, \dots x_n \in \Zbb &&
-x_i + x_j \le c_{ij} &&
x_i \equiv 0 \mod d_i.
\end{align*}
Define $y$ by $y_i = x_i/d_i$. Then $x$ is a solution to the above SDBM iff $y$ is a solution to the following Integer Linear Program (ILP):
\begin{align*}
y_1, \dots y_n \in \Zbb &&
d_j x_j - d_i y_i \le c_{ij}.
\end{align*}

We now prove that solving ILPs of the above form is \NP-hard. Lagarias \cite{lagarias1985simultaneous} proved that it is \NP-hard to solve ILPs of the form
\begin{align*}
y, x_1, \dots x_n \in \Zbb
&& -\frac{s}{t} \le \frac{a_i}{b_i}y - x_i \le \frac{s}{t}
\end{align*}
where $s, t, a_i, b_i \in \Zbb$, $s, t, b_i \ge 1$ and $a_i \ne 0$. Note that if some $a_i < 0$, then 
\begin{align*}
    -\frac{s}{t} \le \frac{a_i}{b_i}y - x_i \le \frac{s}{t} \iff
    -\frac{s}{t} \le \frac{|a_i|}{b_i}y - (-x_i) \le \frac{s}{t}.
\end{align*}
Let $z_i = x_i$ if $a_i > 0$ and $z_i = -x_i$ if $a_i < 0$. Then
the system has a solution iff the following system does:
\begin{align*}
y, z_1, \dots z_n \in \Zbb
&& -\frac{s}{t} \le \frac{|a_i|}{b_i}y - z_i \le \frac{s}{t}
\end{align*}
Thus without loss of generality we can assume $a_i \ge 0$ as well. Now we set $A = \lcm(a_1, \dots a_d)$ and multiply each such pair of inequalities by $t b_i A / a_i$. Note that the latter quantity is a positive integer. We then obtain the system
\begin{align*}
y, z_1, \dots z_n \in \Zbb &&
-\frac{s b_i A}{a_i} \le A t y - \frac{A b_i t}{a_i} z_i \le \frac{s b_i A}{a_i}
\end{align*}
which is of the required form, as all variables always get the same coefficient and these coefficients are integers. We reduced the \NP-hard sub-case of ILP to a form equivalent to SDBM satisfiability, showing that the latter is also \NP-hard.
\end{proof}
% TVPI has already been shown to be \NP-hard~\cite{lagarias1985simultaneous}. \cite{tvpi-rev} claim that TVPI with monotone inequalities can be solved in polynomial time, citing \cite{hochbaum2004monotonizing}, who on the other hand states that it is \NP-hard, in turn citing \cite{lagarias1985simultaneous}. Looking into the proof in the latter work, we can make it work for the monotone uniform coefficient case as well.

\lemSdbmSolInnD*
\begin{proof}
Our proof goes along the same lines as the original paper~\cite{cgst1986sensitivity}. Let $y \in S$ and $z \in S \cap L$. Let $A_1$ be the rows of $A$ such that $A_1 z \ge A_1 y$ and let $A_2$ be the remaining rows, so we have $A_2 z < A_2 y$. Let $C = \{x \in \Rbb^n \mid A_1 x \ge 0 \land A_2 x \le 0\}$; clearly $z - y \in C$. Moreover, $C$ is a polyhedral cone. Let $v_1, \dots v_k$ be the generators of $C$; it can be shown that $v_i$ can be chosen such that they have integer elements and each element has absolute value at most $\MASD(A)$~\cite[Lemma 5.4 on page 103]{korte2013combinatorial}. Then $z - y = \sum_i \lambda_i v_i$ for $\lambda \ge 0$.

Let $x_\mu = z - \sum_i \mu_i v_i = y + \sum_i (\lambda_i - \mu_i) v_i$ for $0 \le \mu \le \lambda$; thus there are two equivalent representations for $x_\mu$. $x_\mu$ is a kind of generalized interpolation between $y$ and $z$. We show that $x_\mu \in S$ since $y$ and $z$ are. The first representation shows that $A_1 x_\mu \le A_1 z \le b_1$ where $b_1$ are the constant terms in $b$ for the rows of $A_1$. The second representation shows that $A_2 x_\mu \le A_2 y \le b_2$ where $b_2$ are the corresponding constant terms. Thus, $x_\mu \in S$.

Now set $\nu_i = \lfloor \lambda_i \rfloor_{\Dlcm}$. Then $x_\nu \in S$ as shown above. Moreover, by the first representation, we are just subtracting multiples of $D$ from each element of $z$ so $x_\nu$ satisfies the congruences, and we have $x_\nu \in S \cap L$. Finally, $x_\nu$ is not too far from $y$:
\begin{align*}
\|x_\nu - y\|_\infty &= \Bigg\|\sum_i (\lambda_i - \lfloor
\lambda_i \rfloor_{\Dlcm}) v_i\Bigg\|_\infty \\
&\le \sum_i (\lambda_i - \lfloor \lambda_i \rfloor_{\Dlcm}) \| v_i \|_\infty \\
& \le nD \MASD (A)
\end{align*}
where the last inequality is because we can assume that at most n of the $\lambda_i$ are non-zero by Carathéodory's theorem for conical hulls.
\end{proof}

\lemMASD*
\begin{proof}
Obviously $\MASD(A) \ge 1$ since we can achieve $1$ by just picking any element $\pm 1$ as the submatrix. We now show that $MASD(A) \le 1$. The given matrix can be thought of as an adjacency list of $m$ directed edges in a graph of $n$ vertices. We can assume that the endpoint with coefficient $-1$ is the source and the destination has $+1$. Let $B$ be a square submatrix, which corresponds to a subset of $k$ vertices and $k$ edges.

If some edge $e$ is chosen without any of its endpoints being chosen, the determinant is zero since $e$'s row only has zeros. If exactly one of $e$'s endpoints is chosen, then by Laplace expansion along $e$'s row, we obtain that the absolute determinant of $B$ is equal to that of the matrix obtained by removing $e$ and the one endpoint of it that is present. If by such removals we obtain an empty matrix then $|\det B| = 1$.

Thus we may assume that all edges that are chosen have both their endpoints chosen as well. Consider the undirected version of the graph. Since the number of edges is equal to the number of vertices in the graph, there exists a cycle. Therefore, by adding up the corresponding rows with coefficients $+1$ if the original direction of the edge is used and $-1$ if the reverse direction is used, we can obtain zero. Thus the matrix is not full rank and has determinant zero.
\end{proof}

