\begin{lemma}
\label{lem:interval-cap}
Let $I_1, \dots I_n$ be intervals with $I_i = [\ell_i, r_i]$. If $|\cap_i I_i| = k$ for $k \in \Nbb$ then either some interval is of size $k$, or the intersection of some two intervals is of size $k$.
\end{lemma}
\begin{proof}
Note that $\cap_i I_i = [\ell_i, r_j]$ for some $i, j \in [n]$. If $i = j$ then $|I_i| = k$, and otherwise $|I_i \cap I_j| = k$.
\end{proof}

